/* Trusted-device convenience is OPT-IN. This is a non-exportable AES-GCM CryptoKey
   in the user's local IndexedDB, NEVER the password. Any script on this site's
   origin can use it: the user must trust this iPhone and the site source. */
const DEVICE_DB='montblanc-trusted-device-v1';
const DEVICE_STORE='vault-keys';
const DEVICE_ID='current-device';
let rememberedDevice=false;
function openDeviceDB(){
 return new Promise((resolve,reject)=>{
  if(!('indexedDB' in window))return reject(Error('Safari не поддерживает локальное хранилище в этом режиме'));
  const req=indexedDB.open(DEVICE_DB,1);
  req.onupgradeneeded=()=>{if(!req.result.objectStoreNames.contains(DEVICE_STORE))req.result.createObjectStore(DEVICE_STORE)};
  req.onsuccess=()=>resolve(req.result);
  req.onerror=()=>reject(req.error||Error('Не удалось открыть хранилище iPhone'));
  req.onblocked=()=>reject(Error('Хранилище занято — закрой другие окна приложения'));
 });
}
async function deviceKeyOp(op,record){
 const db=await openDeviceDB();
 return new Promise((resolve,reject)=>{
  let val=null;
  try{
   const tx=db.transaction(DEVICE_STORE,op==='get'?'readonly':'readwrite');
   const store=tx.objectStore(DEVICE_STORE);
   const req=op==='get'?store.get(DEVICE_ID):op==='set'?store.put(record,DEVICE_ID):store.delete(DEVICE_ID);
   req.onsuccess=()=>{if(op==='get')val=req.result||null};
   tx.oncomplete=()=>{db.close();resolve(val)};
   tx.onerror=()=>{db.close();reject(tx.error||Error('Ошибка хранения ключа iPhone'))};
   tx.onabort=()=>{db.close();reject(tx.error||Error('Операция отменена'))};
  }catch(err){db.close();reject(err)}
 });
}
async function rememberThisDevice(){
 const saved=JSON.parse(requireVaultStorage().getItem(VAULT_KEY)||'null');
 if(!state.local||!localCryptoKey||!saved?.salt)throw Error('Сначала разблокируй дневник');
 if(localCryptoKey.extractable)throw Error('Небезопасный ключ — сохранение отменено');
 await deviceKeyOp('set',{salt:saved.salt,key:localCryptoKey,version:1});
 const check=await deviceKeyOp('get');
 if(!check?.key||check.salt!==saved.salt)throw Error('iPhone не сохранил ключ, режим не включён');
 rememberedDevice=true;
}
async function forgetThisDevice(){await deviceKeyOp('delete');rememberedDevice=false}
async function tryTrustedUnlock(){
 if(!vaultStorage?.getItem(VAULT_KEY))return false;
 let cached;
 try{cached=await deviceKeyOp('get')}catch{return false}
 if(!cached?.key)return false;
 let saved;
 try{saved=JSON.parse(vaultStorage.getItem(VAULT_KEY))}catch{return false}
 if(cached.salt!==saved?.salt){await deviceKeyOp('delete');return false}
 try{
  const decrypted=await crypto.subtle.decrypt({name:'AES-GCM',iv:fromB64(saved.iv)},cached.key,fromB64(saved.ciphertext));
  const obj=JSON.parse(new TextDecoder().decode(decrypted));
  if(!obj?.data||typeof obj.data!=='object')throw Error('Недопустимый формат данных');
  localCryptoKey=cached.key;
  state.data=Object.fromEntries(TABLES.map(t=>[t,Array.isArray(obj.data[t])?obj.data[t]:[]]));
  state.profile=obj.profile||null;state.local=true;state.demo=false;
  state.mode=state.profile?'app':'setup';rememberedDevice=true;lastInteraction=Date.now();
  await ghLoadCredentialFile();render();return true;
 }catch(err){
  // Do not delete the encrypted diary or its remote backup if the local key fails.
  try{await deviceKeyOp('delete')}catch{}
  rememberedDevice=false;localCryptoKey=null;return false;
 }
}

