function localDate(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function plusDays(date,days){const d=new Date(`${date}T12:00:00`);d.setDate(d.getDate()+days);return localDate(d)}
function monthKey(d){return String(d||'').slice(0,7)}
function ruDate(str){if(!str)return '—';const d=new Date(`${String(str).slice(0,10)}T12:00:00`);return Number.isNaN(d.getTime())?String(str):new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',year:'numeric'}).format(d)}
function e(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function num(x){const n=Number(x);return Number.isFinite(n)?n:0}
function money(x){return '€'+num(x).toLocaleString('ru-RU',{maximumFractionDigits:2})}
function clamp(n,a=0,b=100){return Math.max(a,Math.min(b,n))}
function avg(xs){return xs.length?xs.reduce((a,b)=>a+num(b),0)/xs.length:0}
function deltaDays(from,to=today()){return Math.max(0,Math.floor((new Date(`${to}T12:00:00`)-new Date(`${from}T12:00:00`))/864e5))}
