function renderLanding(){const existing=Boolean(vaultStorage?.getItem(VAULT_KEY));root.innerHTML=`<section class="auth-page"><div class="auth-panel local-entry"><div class="auth-brand"><span class="brand-icon brand-mountain">🏔</span> MONTBLANC <span class="pill">iPHONE · 14.0.1</span></div><div class="entry-mountain"><img src="./mountain-hero.webp" alt="Вершина Монблан на рассвете" /></div><h1>От базового лагеря<br><span class="accent">к своей вершине.</span></h1><p>Цели, заработок, английский, обучение, привычки и честная аналитика прогресса. Настоящий личный дневник — только после включения защищённого хранения.</p><div class="local-card"><b>🔒 Личный режим на этом устройстве</b><p class="small muted mt8">Данные сохраняются зашифрованными AES-GCM под твоим паролем. Без отдельной базы: можно подключить зашифрованную копию в приватный GitHub.</p><button class="button mt14" data-action="local-open" ${vaultStorage?'':'disabled title="Хранилище недоступно"'}>${existing?'Открыть MONTBLANC':'Начать личную экспедицию'} ${icon('arrow')}</button></div><div class="notice mt20">Для реальных записей используйте устройство, которому доверяете, и надёжный пароль. Резервную копию нужно хранить отдельно. Шифрование не защищает от вредоносных расширений, взломанного устройства или подменённого кода сайта.</div><button class="button secondary mt14" data-action="demo">Смотреть демонстрацию (вымышленные данные)</button><button class="button secondary mt14" data-action="github-restore">🔐 Восстановить с GitHub</button><div class="mt14"><label class="small muted" for="vault-restore-file">Восстановить зашифрованный архив</label><input id="vault-restore-file" type="file" accept=".json,application/json" class="control mt8"/></div><p class="small muted mt20">${configReady?'Также можно использовать облачный вход Supabase после настройки.':'После подключения PRIVATE GitHub-архива можно восстановить историю после удаления приложения или смены телефона.'}</p></div></section>`}
function renderLocalAuth(){const existing=Boolean(vaultStorage?.getItem(VAULT_KEY));root.innerHTML=`<section class="auth-page"><div class="auth-panel local-entry"><div class="auth-brand"><span class="brand-icon brand-mountain">🏔</span> MONTBLANC <span class="pill">PRIVATE · LOCAL</span></div><h1>${existing?'Твоё пространство.':'Создай личное пространство.'}</h1><p>${existing?'Введи пароль, чтобы расшифровать записи на этом устройстве.':'Придумай уникальный пароль не короче 12 символов. Мы не сможем его восстановить.'}</p><form data-form="local-auth" class="stack"><div class="form-field"><label for="vault-pass">Пароль</label><input id="vault-pass" class="control" name="password" type="password" minlength="12" autocomplete="${existing?'current-password':'new-password'}" required/></div>${existing?'':`<div class="form-field"><label for="vault-confirm">Повтори пароль</label><input id="vault-confirm" class="control" name="confirm_password" type="password" minlength="12" autocomplete="new-password" required/></div>`}${existing?`<label class="device-remember"><input type="checkbox" name="remember_device" value="yes"><span><b>Запомнить этот iPhone</b><small>Открывать без пароля на этом устройстве. Удобнее, но менее защищено, чем ввод пароля каждый раз.</small></span></label>`:''}<button class="button" type="submit">${existing?'Разблокировать':'Начать личную экспедицию'} ${icon('arrow')}</button></form><button class="button ghost mt14" data-action="back-landing">← Назад</button><div class="safe mt20">${existing?'Если пароль потерян, данные без резервной копии и пароля восстановить нельзя.':'В этом режиме данные сохраняются в зашифрованном виде только в браузере. Нужна отдельная копия на случай очистки браузера.'}</div></div></section>`}
const utf8=(str)=>new TextEncoder().encode(str);
const b64=(a)=>{let binary="";for(let i=0;i<a.length;i+=32768)binary+=String.fromCharCode(...a.subarray(i,i+32768));return btoa(binary)};
const fromB64=(s)=>Uint8Array.from(atob(s),x=>x.charCodeAt(0));
async function deriveVaultKey(password,salt){const material=await crypto.subtle.importKey('raw',utf8(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},material,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function sealVault(key,content,salt){const iv=crypto.getRandomValues(new Uint8Array(12));const ciphertext=await crypto.subtle.encrypt({name:'AES-GCM',iv},key,utf8(JSON.stringify(content)));return {format:'life-os-v3-encrypted',version:3,iterations:310000,salt:b64(salt),iv:b64(iv),ciphertext:b64(new Uint8Array(ciphertext)),updated_at:new Date().toISOString()}}
// Separate encrypted credentials live ONLY on this iPhone, never in remote encrypted vault.
async function ghEncryptCredentialFile(){if(!state.local||!localCryptoKey||!github.token)return;const iv=crypto.getRandomValues(new Uint8Array(12));const payload={repo:github.repo,token:github.token,sha:github.sha,lastHash:github.lastHash,lastSent:github.lastSent};const raw=await crypto.subtle.encrypt({name:'AES-GCM',iv},localCryptoKey,utf8(JSON.stringify(payload)));requireVaultStorage().setItem(GH_AUTH_KEY,JSON.stringify({version:1,iv:b64(iv),ciphertext:b64(new Uint8Array(raw))}))}
async function ghLoadCredentialFile(){const raw=vaultStorage?.getItem(GH_AUTH_KEY);if(!raw||!localCryptoKey)return;try{const blob=JSON.parse(raw),plaintext=await crypto.subtle.decrypt({name:'AES-GCM',iv:fromB64(blob.iv)},localCryptoKey,fromB64(blob.ciphertext));const saved=JSON.parse(new TextDecoder().decode(plaintext));github.repo=parseRepo(saved.repo);github.token=saved.token;github.sha=saved.sha||'';github.lastHash=saved.lastHash||'';github.lastSent=saved.lastSent||'';github.status='Подключено · проверка соединения';const current=await ghHashVault();if(current!==github.lastHash){github.dirty=true;ghScheduleBackup()}else github.status='Последняя копия: '+(github.lastSent?new Date(github.lastSent).toLocaleString('ru-RU'):'ранее')}catch(e){github.status='GitHub не подключён. Проверь настройки.';github.repo='';github.token='';github.sha='';github.lastHash=''}}
async function ghHashVault(){const raw=vaultStorage?.getItem(VAULT_KEY)||'';const digest=await crypto.subtle.digest('SHA-256',utf8(raw));return [...new Uint8Array(digest)].map(b=>b.toString(16).padStart(2,'0')).join('')}
function ghScheduleBackup(){if(!state.local||!github.token||!github.repo)return;github.generation++;github.dirty=true;github.status='Есть изменения · ожидают отправки';clearTimeout(github.timer);github.timer=setTimeout(()=>{void ghBackupNow(false).catch(e=>{github.status=e.message;console.warn('GitHub encrypted backup:',e.message)})},12000)}
async function ghBackupNow(force=true){if(github.busy||!state.local||!github.token)return false;clearTimeout(github.timer);github.busy=true;const generation=github.generation;github.status='Отправка зашифрованной копии…';try{await vaultWriteQueue;const raw=requireVaultStorage().getItem(VAULT_KEY);if(!raw)throw Error('Локальный дневник не найден');const currentHash=await ghHashVault();if(!force&&currentHash===github.lastHash){github.dirty=false;return true}const remote=await readRemoteVault(github.repo,github.token);if(remote.exists&&remote.sha!==github.sha)throw Error('В GitHub появилась другая версия. Автозапись остановлена, чтобы не затереть данные. Используй восстановление.');if(!remote.exists&&github.sha)throw Error('Архив исчез из GitHub. Автозапись приостановлена до проверки.');const newSha=await writeRemoteVault(github.repo,github.token,JSON.parse(raw),remote.sha);if(!newSha)throw Error('GitHub не подтвердил SHA сохранения');github.sha=newSha;github.lastHash=currentHash;github.lastSent=new Date().toISOString();github.dirty=(github.generation!==generation);github.status=github.dirty?'Есть более новые изменения · отправим отдельно':'Сохранено в приватном GitHub · '+new Date().toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'});await ghEncryptCredentialFile();if(github.dirty)ghScheduleBackup();return true}catch(err){github.dirty=true;github.status='Не отправлено: '+err.message;throw err}finally{github.busy=false}}
async function ghConfigure(repo,token){if(!state.local||!localCryptoKey)throw Error('Сначала открой защищённый дневник');repo=parseRepo(repo);await verifyPrivateRepo(repo,token);const remote=await readRemoteVault(repo,token);if(remote.exists){if(!confirm('В этом репозитории уже есть архив MONTBLANC. Заменить его текущими записями? Если это старый дневник, нажми «Отмена» и восстанови его через стартовый экран.'))return false}github.repo=repo;github.token=token;github.sha=remote.sha;github.lastHash='';github.dirty=true;github.status='Подключено · начинаем отправку';await ghEncryptCredentialFile();await ghBackupNow();return true}
function ghDisconnect(){clearTimeout(github.timer);vaultStorage?.removeItem(GH_AUTH_KEY);github.repo='';github.token='';github.sha='';github.lastHash='';github.lastSent='';github.dirty=false;github.status='Не подключено'}
async function ghRestoreDialog(){const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML=`<div class="modal" role="dialog" aria-modal="true" aria-label="Восстановить с GitHub"><h2>Восстановление из приватного GitHub</h2><p class="small muted mt14">Укажи приватный репозиторий, токен с правом Contents и пароль от зашифрованного дневника. GitHub хранит архив, но не знает пароль.</p><form id="gh-restore-form" class="stack mt20"><div class="form-field"><label>Репозиторий (владелец/название)</label><input class="control" name="repo" value="dmitriydizdar2020-cyber/montblanc-private-data" required></div><div class="form-field"><label>GitHub token</label><input type="password" name="token" class="control" autocomplete="off" required></div><div class="form-field"><label>Пароль от дневника MONTBLANC</label><input type="password" name="password" minlength="12" autocomplete="current-password" class="control" required></div><p class="small" id="gh-restore-status" role="alert"></p><div class="form-actions"><button type="button" class="button secondary" id="gh-close">Отмена</button><button type="submit" class="button" id="gh-submit">Восстановить</button></div></form></div>`;document.body.append(overlay);overlay.querySelector('#gh-close').addEventListener('click',()=>overlay.remove());overlay.querySelector('#gh-restore-form').addEventListener('submit',async ev=>{ev.preventDefault();const f=ev.target,button=f.querySelector('#gh-submit');button.disabled=true;try{const repo=f.elements.repo.value,token=f.elements.token.value,pass=f.elements.password.value;await verifyPrivateRepo(repo,token);const remote=await readRemoteVault(repo,token);if(!remote.exists)throw Error('В GitHub ещё нет сохранённого дневника');await verifyEncryptedArchive(remote.value,pass);if(vaultStorage?.getItem(VAULT_KEY)&&!confirm('Заменить текущие записи проверенным архивом из GitHub?'))return;requireVaultStorage().setItem(VAULT_KEY,JSON.stringify(remote.value));vaultStorage?.removeItem(GH_AUTH_KEY);github.repo='';github.token='';await openLocal(pass);github.repo=repo;github.token=token;github.sha=remote.sha;github.lastHash=await ghHashVault();github.lastSent=new Date().toISOString();github.status='Восстановлено из GitHub';github.dirty=false;await ghEncryptCredentialFile();overlay.remove();notify('Архив восстановлен и GitHub подключён.');}catch(e){f.querySelector('#gh-restore-status').textContent=e.message;button.disabled=false}})}
window.addEventListener('online',()=>{if(state.local&&github.dirty)ghScheduleBackup()});

let vaultWriteQueue=Promise.resolve();
async function persistLocal(){if(!state.local||!localCryptoKey)return;const old=JSON.parse(vaultStorage?.getItem(VAULT_KEY)||'null');if(!old)throw Error('Зашифрованное хранилище не найдено');const snapshot=JSON.stringify({profile:state.profile,data:state.data}),salt=fromB64(old.salt),key=localCryptoKey;vaultWriteQueue=vaultWriteQueue.catch(()=>{}).then(async()=>{const secured=await sealVault(key,JSON.parse(snapshot),salt);if(state.local&&localCryptoKey===key){requireVaultStorage().setItem(VAULT_KEY,JSON.stringify(secured));ghScheduleBackup()}});return vaultWriteQueue} 
async function openLocal(password){requireVaultStorage();if(!globalThis.crypto?.subtle)throw Error('Шифрование доступно только в безопасном окружении HTTPS или localhost.');const saved=JSON.parse(vaultStorage?.getItem(VAULT_KEY)||'null');if(!saved){const salt=crypto.getRandomValues(new Uint8Array(16));localCryptoKey=await deriveVaultKey(password,salt);state.data=Object.fromEntries(TABLES.map(k=>[k,[]]));state.profile=null;state.local=true;state.demo=false;requireVaultStorage().setItem(VAULT_KEY,JSON.stringify(await sealVault(localCryptoKey,{profile:null,data:state.data},salt)));state.mode='setup';render();return}
 if(saved.format!=='life-os-v3-encrypted'||saved.version!==3)throw Error('Неизвестный формат шифрованного архива');const key=await deriveVaultKey(password,fromB64(saved.salt));const decrypted=await crypto.subtle.decrypt({name:'AES-GCM',iv:fromB64(saved.iv)},key,fromB64(saved.ciphertext));const obj=JSON.parse(new TextDecoder().decode(decrypted));if(!obj?.data||typeof obj.data!=='object')throw Error('Повреждённый архив');localCryptoKey=key;state.data=Object.fromEntries(TABLES.map(t=>[t,Array.isArray(obj.data[t])?obj.data[t]:[]]));state.profile=obj.profile||null;state.local=true;state.demo=false;state.mode=state.profile?'app':'setup';lastInteraction=Date.now();await ghLoadCredentialFile();render()}
function lockLocal(){clearTimeout(github.timer);github.token='';github.status='Заблокировано';localCryptoKey=null;state.data=Object.fromEntries(TABLES.map(t=>[t,[]]));state.profile=null;state.local=false;state.mode='local-auth';state.modal=null;render()}
async function downloadEncrypted(){await vaultWriteQueue;const val=vaultStorage?.getItem(VAULT_KEY);if(!val)throw Error('Нет резервной копии');const a=document.createElement('a');const url=URL.createObjectURL(new Blob([val],{type:'application/json'}));a.href=url;a.download=`life-os-encrypted-backup-${today()}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function renderAuth(){root.innerHTML=`<section class="auth-page"><div class="auth-panel"><div class="auth-brand"><span class="brand-icon brand-mountain">🏔</span> MONTBLANC <span class="pill">PRIVATE</span></div><h1>Твоё пространство.<br><span class="accent">Твои правила.</span></h1><p>Вход только для владельца. Данные защищены входом и индивидуальными правилами доступа к базе.</p><form class="auth-form" data-form="login">${field('email','Электронная почта','email','','autocomplete="email" required')}${field('password','Пароль','password','','autocomplete="current-password" required minlength="6"')}<button class="button" type="submit">Войти ${icon('arrow')}</button></form><div class="safe mt20">Нет регистрации для посторонних. Владелец создаётся в панели Supabase, а открытая регистрация отключается.</div></div></section>`}
function renderSetup(){root.innerHTML=`<section class="auth-page"><div class="setup-hero"><div class="card"><div class="eyebrow">Первый запуск · Приватная настройка</div><h1 class="setup-heading" style="margin-top:13px">Давай зафиксируем<br><span class="accent">твою точку А.</span></h1><p class="muted mb14" style="line-height:1.6">Введённые цифры сохранятся в зашифрованном хранилище этого устройства или в защищённой базе при облачном входе. Ничего личного не записывается в исходный код сайта.</p><form data-form="setup" class="stack"><div class="form-grid">${field('income_baseline','Стабильный доход сейчас, €/мес','number','0','min="0" step="0.01" required')}${field('debt_baseline','Текущий долг, €','number','0','min="0" step="0.01" required')}${field('goal_90','Цель дохода на 90 дней, €','number','1500','min="0" step="1" required')}${field('goal_year','Цель на 12 месяцев, €','number','2500','min="0" step="1" required')}${field('social_baseline','Соцсети в среднем, мин/день','number','120','min="0" step="1" required')}${field('sport_baseline','Тренировок в неделю','number','1','min="0" max="14" step="1" required')}${field('focus_title','Мой фокус на ближайшие 14 дней','text','Проверить спрос и получить первого клиента','required')}</div>${field('why_text','Ради чего я начинаю?','textarea','','placeholder="Пиши своими словами, не нужно идеальных формулировок"')}${field('vision_text','Как я хочу жить через год?','textarea','','placeholder="Три конкретные перемены"')}<div class="safe">Это не экзамен. Данные можно изменить в разделе «Настройки».</div><div class="form-actions"><button type="submit" class="button">Начать восхождение ${icon('arrow')}</button></div></form></div></div></section>`}
function renderShell(){
 const active=tabForPage(state.page),title=e(SECTION_NAMES[state.page]||shellTitle());
 const backup=state.demo?'Демонстрация':(github.token?'GitHub подключён':'Локальное хранение');
 const backupSymbol=github.token?'●':'○';
 const shortNav=MAIN_TABS.map(([id,label,ico])=>`<button class="mb7-side-link ${active===id?'selected':''}" data-page="${id}" aria-current="${active===id?'page':'false'}">${icon(ico)}<span>${label}</span></button>`).join('');
 root.innerHTML=`<div class="shell mb7-shell mb12-shell">
 <aside class="mb7-sidebar"><button class="mb7-side-brand" data-page="dashboard"><img src="./icon-192.png" alt=""><span>MONTBLANC<small>FROM ZERO TO SUMMIT</small></span></button><p class="mb7-side-label">МОЯ ЭКСПЕДИЦИЯ</p><nav class="mb7-side-nav">${shortNav}</nav><div class="mb7-side-bottom"><div class="mb7-side-status"><span class="mb7-indicator"></span>${e(backup)}</div><span>Твой путь. Твой темп.</span></div></aside>
 <main class="main mb7-main"><header class="mb7-topbar"><div class="mb7-top-left"><img src="./icon-192.png" alt="" class="mb7-head-logo"><div><span class="mb7-head-brand">MONTBLANC <small class="c60-version">v14.0.1</small></span><span class="mb7-head-subtitle">${title}</span></div></div><button class="mb7-backup-status" data-page="settings" aria-label="Настройки и сохранение данных"><span class="mb7-status-dot">${backupSymbol}</span><span>${e(backup)}</span>${icon('settings')}</button></header>
 ${state.demo?'<div class="mb7-demo">Демо-режим: данные вымышлены и не сохраняются.</div>':''}
 <div class="content mb7-content">${renderPage()}</div></main>
 <nav class="mobile-dock mb7-dock" aria-label="Основные разделы">${MAIN_TABS.map(([id,label,ico])=>`<button data-page="${id}" aria-label="${label}" aria-current="${active===id?'page':'false'}" class="${active===id?'active':''}">${icon(ico)}<span>${label}</span></button>`).join('')}</nav></div>
 ${state.modal?renderModal(state.modal):''}`;
}

function pageHead(kicker,title,sub,button=''){return `<div class="pagehead"><div><div class="eyebrow">${e(kicker)}</div><h1 style="margin-top:10px">${e(title)}</h1><p>${e(sub)}</p></div>${button}</div>`}
function kpi(label,value,meta,ic='target',cls=''){return `<div class="card"><div class="spread"><div class="kpi-label">${e(label)}</div><div class="kpi-icon">${icon(ic)}</div></div><div class="kpi-value ${cls}">${value}</div><div class="kpi-meta">${e(meta)}</div></div>`}
function progress(goal){const a=num(goal.start_value),c=num(goal.current_value),t=num(goal.target_value);if(goal.direction==='down'){if(a<=t)return c<=t?100:0;return clamp(100*(a-c)/(a-t))}if(t<=a)return c>=t?100:0;return clamp(100*(c-a)/(t-a))}
function measuredGoal(g){const st=weekStats();switch(g.metric_key){case 'annual_income':{const span=routeAnnualSpan();return {...g,current_value:state.data.finance_entries.filter(x=>x.kind==='income'&&x.entry_date>=span.start&&x.entry_date<=span.end).reduce((s,x)=>s+num(x.amount_eur),0)}}case 'annual_sport':{const span=routeAnnualSpan();return {...g,current_value:routeSportSessions(span.start,span.end)}}case 'annual_english_hours':{const span=routeAnnualSpan();return {...g,current_value:Math.round(state.data.daily_logs.filter(x=>x.log_date>=span.start&&x.log_date<=span.end).reduce((s,x)=>s+num(x.english_min),0)/6)/10}}case 'debt_remaining':return {...g,current_value:currentDebt()};case 'monthly_income':return {...g,current_value:monthIncome()};case 'weekly_sport':return {...g,current_value:st.sport};case 'daily_english':return {...g,current_value:st.logs?Math.round(st.english/st.logs):0};case 'weekly_english':return {...g,current_value:st.english};case 'daily_learning':return {...g,current_value:st.logs?Math.round(st.learning/st.logs):0};case 'reserve_rate':return {...g,current_value:monthIncome()>0?Math.round(100*monthReserve()/monthIncome()):0};case 'english_skill':{const skills=['speaking','listening','reading','writing'],level={A1:1,A2:2,B1:3},checks=state.data.skill_checks||[];const grades=skills.map(k=>{const last=checks.filter(x=>x.skill===k).sort((a,b)=>String(b.assessed_on).localeCompare(String(a.assessed_on)))[0];return level[last?.level]||1});return {...g,current_value:Math.round(avg(grades)*100)/100}}case 'weekly_family':return {...g,current_value:st.family};case 'daily_social':return {...g,current_value:st.socialAverage===null?num(g.start_value):st.socialAverage};default:return g}}
function overallProgress(){const gs=state.data.goals.filter(x=>x.horizon==='90'&&x.status!=='paused');return gs.length?Math.round(avg(gs.map(g=>progress(measuredGoal(g))))):0}
function currentDebt(){const snapshots=state.data.finance_entries.filter(x=>x.kind==='debt_balance').sort((a,b)=>String(b.entry_date).localeCompare(String(a.entry_date))||String(b.created_at||'').localeCompare(String(a.created_at||'')));return snapshots.length?num(snapshots[0].amount_eur):num(state.profile?.debt_baseline)}
function monthIncome(month=monthKey(today())){return state.data.finance_entries.filter(x=>x.kind==='income'&&monthKey(x.entry_date)===month).reduce((sum,x)=>sum+num(x.amount_eur),0)}
function monthReserve(month=monthKey(today())){return state.data.finance_entries.filter(x=>monthKey(x.entry_date)===month&&(x.kind==='reserve'||x.kind==='reserve_withdrawal')).reduce((s,x)=>s+(x.kind==='reserve'?num(x.amount_eur):-num(x.amount_eur)),0)}
function reserveBalance(){return state.data.finance_entries.reduce((s,x)=>s+(x.kind==='reserve'?num(x.amount_eur):x.kind==='reserve_withdrawal'?-num(x.amount_eur):0),0)}
function addMonths(date,count){const d=new Date(`${date}T12:00:00`);const day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+count);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));return localDate(d)}
function logBetween(from,to){return state.data.daily_logs.filter(x=>x.log_date>=from&&x.log_date<=to)}
function sumOf(rows,key){return rows.reduce((s,x)=>s+num(x[key]),0)}
function changeHint(current,previous,unit=''){if(previous===null)return 'Нет данных для сравнения';const diff=Math.round(current-previous);return `${diff>0?'+':''}${diff} ${unit} к предыдущему периоду`}
function lastDays(n=7){return Array.from({length:n},(_,i)=>plusDays(today(),i-(n-1)))}
function weekLogs(){const start=plusDays(today(),-6);return state.data.daily_logs.filter(x=>x.log_date>=start&&x.log_date<=today())}
function weekStats(){const logs=weekLogs(),sum=k=>logs.reduce((a,x)=>a+num(x[k]),0);return {logs:logs.length,focus:sum('focus_min'),english:sum('english_min'),learning:sum('learning_min'),learningDays:logs.filter(x=>num(x.learning_min)>=60).length,englishDays:logs.filter(x=>num(x.english_min)>=60).length,sport:v9Period('week').sport,family:sum('family_min'),socialAverage:logs.length?Math.round(avg(logs.map(x=>x.social_min))):null,sleepAverage:logs.filter(x=>x.sleep_hours!==null&&x.sleep_hours!==undefined).length?avg(logs.filter(x=>x.sleep_hours!==null&&x.sleep_hours!==undefined).map(x=>x.sleep_hours)):null,energyAverage:logs.some(x=>x.energy!=null)?avg(logs.filter(x=>x.energy!=null).map(normalizedEnergy)):null,completed:state.data.tasks.filter(t=>t.completed&&t.task_date>=plusDays(today(),-6)&&t.task_date<=today()).length}}
function goalCards(list){if(!list.length)return '<div class="empty">Пока нет целей. Начни с одной измеримой.</div>';return list.map(original=>{const g=measuredGoal(original),percent=Math.round(progress(g)),start=state.profile?.started_at||today(),total=g.deadline?Math.max(1,deltaDays(start,g.deadline)):0,passed=g.deadline?clamp(deltaDays(start,today())/total*100):0,habit=['weekly_sport','weekly_english','daily_learning','weekly_family','daily_social','reserve_rate'].includes(g.metric_key),noData=(g.metric_key==='reserve_rate'&&monthIncome()<=0)||(['weekly_sport','weekly_english','daily_learning','weekly_family','daily_social'].includes(g.metric_key)&&weekStats().logs===0)||(g.metric_key==='monthly_income'&&!state.data.finance_entries.some(x=>x.kind==='income'&&monthKey(x.entry_date)===monthKey(today()))),status=noData?'Недостаточно данных':percent>=100?'Цель достигнута':habit?'Текущий ритм':passed>65&&percent<25?'Нужно скорректировать план':'В работе';return `<div class="goal"><div class="goal-main"><div><span class="pill gray">${e(catLabel(g.category))}</span><h3 class="mt8">${e(g.title)}</h3><p class="small muted mt8">${e(g.description||'')}${g.deadline?' · срок: '+ruDate(g.deadline):''}</p></div><div class="goal-list-actions"><button class="button small secondary" data-action="edit-goal" data-id="${e(g.id)}">Изменить</button>${percent<100&&!g.metric_key?`<button class="button small ghost" data-action="goal-complete" data-id="${e(g.id)}">✓ Достигнута</button>`:''}</div></div><div class="spread small"><span>Сейчас: <b>${e(g.current_value)} ${e(g.unit)}</b> · цель: <b>${e(g.target_value)} ${e(g.unit)}</b></span><span class="accent">${noData?'—':percent+'%'}</span></div><div class="progress-track"><div class="progress-fill" style="width:${noData?0:percent}%"></div></div>${g.deadline?`<div class="spread micro muted"><span>${e(status)}</span><span>До ${ruDate(g.deadline)}</span></div>`:`<div class="micro muted">${e(status)}</div>`}${g.next_action?`<p class="small muted mt14">Следующий шаг: ${e(g.next_action)}</p>`:''}${(()=>{const work=(state.data.tasks||[]).filter(t=>t.goal_id===g.id);return work.length?`<div class="mb9-linked-tasks"><span>✓ Выполнено шагов по этой цели: ${work.filter(taskIsDone).length} / ${work.length}</span><div class="progress-track"><div class="progress-fill" style="width:${Math.round(100*work.filter(taskIsDone).length/work.length)}%"></div></div></div>`:''})()}</div>`}).join('')}
function catLabel(s){return ({finance:'Доход',health:'Тело',sport:'Спорт',growth:'Развитие',family:'Семья',focus:'Концентрация',travel:'Путешествия',capital:'Капитал',other:'Другое'})[s]||'Другое'}
function svgChart(values,labels,{target=null,min=0,max=null,format='number'}={}){const W=680,H=240,L=51,R=17,T=19,B=41;const actual=values.map(v=>v===null||v===undefined?null:num(v));const seen=actual.filter(v=>v!==null);const hi=Math.max(max??0,target??0,...seen,1),lo=Math.min(min,0);const span=Math.max(1,hi-lo);const x=i=>L+(W-L-R)*(i/Math.max(1,values.length-1)),y=v=>T+(H-T-B)*(1-(v-lo)/span);const pts=actual.map((v,i)=>v===null?null:[x(i),y(v)]);const groups=[];let g=[];for(const p of pts){if(p)g.push(p);else if(g.length){groups.push(g);g=[]}}if(g.length)groups.push(g);const paths=groups.map(s=>{const d=s.map((p,i)=>`${i?'L':'M'}${p[0].toFixed(1)},${p[1].toFixed(1)}`).join(' ');const area=d+` L${s.at(-1)[0].toFixed(1)},${y(lo)} L${s[0][0].toFixed(1)},${y(lo)} Z`;return `<path d="${area}" fill="url(#area-life)"/><path class="chart-line" d="${d}"/>`}).join('');const fmt=v=>format==='money'?money(v):Math.round(v).toLocaleString('ru-RU');const tickIndices=new Set([0,Math.round((values.length-1)/4),Math.round((values.length-1)/2),Math.round(3*(values.length-1)/4),values.length-1]);return `<svg class="chart" role="img" aria-label="График изменений, пустые значения означают отсутствие записи" viewBox="0 0 ${W} ${H}"><defs><linearGradient id="area-life" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#4b89ff" stop-opacity=".26"/><stop offset="100%" stop-color="#4b89ff" stop-opacity=".015"/></linearGradient></defs>${Array.from({length:5},(_,i)=>{const yy=T+(H-T-B)*i/4;return `<line class="chart-grid" x1="${L}" x2="${W-R}" y1="${yy}" y2="${yy}"/><text class="chart-label" x="${L-9}" y="${yy+4}" text-anchor="end">${e(fmt(hi-(hi-lo)*i/4))}</text>`}).join('')}${target!==null?`<line x1="${L}" x2="${W-R}" y1="${y(target)}" y2="${y(target)}" stroke="#cf9e51" stroke-width="1.5" stroke-dasharray="6 6"/>`:''}${paths}${pts.map((p,i)=>p?`<circle class="chart-dot" cx="${p[0]}" cy="${p[1]}" r="3.2"><title>${e(labels[i])}: ${e(fmt(actual[i]))}</title></circle>`:'').join('')}${labels.map((l,i)=>tickIndices.has(i)?`<text class="chart-label" x="${x(i)}" y="${H-12}" text-anchor="middle">${e(l)}</text>`:'').join('')}</svg>${!seen.length?'<p class="small muted">Пока нет записей. Отсутствие данных не считается нулевым результатом.</p>':''}`}
function ring(pct,title,center,{size=126,color='#366ce5',dark=false}={}){const radius=42,circ=2*Math.PI*radius,dash=circ*clamp(pct)/100;return `<div class="ring-wrap" style="width:${size}px;height:${size}px"><svg viewBox="0 0 110 110" width="${size}" height="${size}" aria-label="${e(title||'Прогресс')}: ${Math.round(pct)}%"><circle cx="55" cy="55" r="42" stroke="${dark?'#ffffff30':'#e8edf4'}" stroke-width="10" fill="none"/><circle cx="55" cy="55" r="42" stroke="${color}" stroke-width="10" stroke-linecap="round" fill="none" stroke-dasharray="${dash} ${circ}" transform="rotate(-90 55 55)"/><text x="55" y="56" dominant-baseline="middle" text-anchor="middle" fill="${dark?'#fff':'#192a42'}" font-size="${String(center).length>9?13:16}" font-weight="770">${e(center)}</text></svg>${title?`<span class="ring-label">${e(title)}</span>`:''}</div>`}
function incomeChart(){const months=Array.from({length:6},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-(5-i));return localDate(d).slice(0,7)});const values=months.map(m=>state.data.finance_entries.some(x=>x.kind==='income'&&monthKey(x.entry_date)===m)?monthIncome(m):null);return svgChart(values,months.map(m=>{const dt=new Date(`${m}-01T12:00:00`);return new Intl.DateTimeFormat('ru-RU',{month:'short'}).format(dt)}),{target:num(state.profile?.goal_90)||1500,format:'money'})}
function heatmap(){return `<div class="calendar-heat">${lastDays(28).map(date=>{const d=state.data.daily_logs.find(x=>x.log_date===date);const tasks=state.data.tasks.filter(x=>x.task_date===date);const score=d?(num(d.focus_min)>=30?2:1)+(num(d.english_min)>=10?1:0)+(tasks.some(x=>x.completed)?1:0):0;return `<div class="heatcell ${score===0?'':score===1?'low':score===2?'medium':'high'}" title="${e(date)} · ${d?'есть запись':'без записи'}"></div>`}).join('')}</div><p class="footnote mt8">28 дней · более яркий цвет означает больше выполненных небольших действий. Пустые дни не обнуляют прогресс.</p>`}
function todayTasks(){const items=state.data.tasks.filter(t=>t.task_date&&t.task_date<=today()&&t.status!=='cancelled'&&t.status!=='skipped').sort((a,b)=>(Number(a.completed)-Number(b.completed))||String(a.task_date).localeCompare(String(b.task_date)));return items.length?items.slice(0,8).map(t=>`<div class="task ${t.completed?'done':''}"><button class="check ${t.completed?'checked':''}" aria-label="${t.completed?'Отменить отметку':'Выполнить задачу'}" data-action="toggle-task" data-id="${e(t.id)}">${t.completed?'✓':''}</button><div style="flex:1"><div class="task-title">${e(t.title)}</div><div class="task-meta">${e(catLabel(t.category))} · ${e(t.task_date===today()?'Сегодня':ruDate(t.task_date))} ${t.is_main?'· Главный шаг':''}</div></div><button class="iconbtn" data-action="edit-task" data-id="${e(t.id)}" aria-label="Изменить задачу">···</button></div>`).join(''):'<div class="empty">Сегодня пока нет задач. Выбери одно реальное действие.</div>'}
function salesSummary(days=30){const logs=logBetween(plusDays(today(),1-days),today());return {days:logs.length,contacts:sumOf(logs,'sales_contacts'),replies:sumOf(logs,'sales_replies'),calls:sumOf(logs,'sales_calls'),offers:sumOf(logs,'sales_offers'),paid:sumOf(logs,'sales_paid')}}
function growthSignals(){const logs=weekLogs(),n=logs.length,s=salesSummary(7);if(n<4)return {score:null,coverage:n,signals:[],reason:'Для честного Growth Score нужны хотя бы 4 записи за 7 дней.'};const vals=[{name:'Реальные контакты',value:clamp(s.contacts/Math.max(1,n*8)*100),weight:.30,detail:`${s.contacts} контактов · цель ≈${n*8}`},{name:'Английский',value:clamp(sumOf(logs,'english_min')/(60*n)*100),weight:.22,detail:`${sumOf(logs,'english_min')} минут`},{name:'Учёба',value:clamp(sumOf(logs,'learning_min')/(60*n)*100),weight:.18,detail:`${sumOf(logs,'learning_min')} минут`},{name:'Спорт',value:clamp(logs.filter(x=>num(x.exercise_min)>=20).length/3*100),weight:.15,detail:'3 тренировки за неделю'},{name:'Концентрация',value:clamp(sumOf(logs,'focus_min')/(90*n)*100),weight:.15,detail:'90 минут за день с записью'}];return {score:Math.round(vals.reduce((sum,v)=>sum+v.value*v.weight,0)),coverage:n,signals:vals,reason:'Индекс отражает регулярность действий, НЕ рост дохода, владение английским или ценность человека.'}}
function growthAdvice(){const s=salesSummary(7),g=growthSignals();if(g.coverage<4)return 'Сначала записывай действия хотя бы четыре дня. Без данных приложение не будет угадывать причину отставания.';if(s.contacts<10)return 'Главное узкое место — мало контактов с клиентами. Выбери одну услугу и отправь пять адресных предложений сегодня.';if(s.contacts>=20&&s.replies===0)return 'Контакты есть, но ответов нет. Пересмотри сегмент, текст сообщения и конкретную пользу для покупателя.';if(s.replies>=5&&s.offers===0)return 'Есть интерес, но нет офферов. Сформулируй цену и предложи клиенту следующий шаг.';if(s.offers>=5&&s.paid===0)return 'Есть предложения, но нет оплат. Разбери пять возражений, проверь ценность и качество оффера.';return 'Продолжай одну выбранную гипотезу. Сопоставляй реальные оплаченные заказы с действиями, а не только с часами работы.'}
function renderSales(){const t=state.data.daily_logs.find(x=>x.log_date===today())||{},s=salesSummary(30),n=salesSummary(7),logs=lastDays(30),recorded=logBetween(plusDays(today(),-29),today()).length;const cells=[['Контакты',s.contacts,'Охват потенциальных клиентов'],['Ответы',s.replies,'Значимый ответ'],['Разговоры',s.calls,'Созвоны и переговоры'],['Предложения',s.offers,'Отправленные офферы'],['Оплаты',s.paid,'Подтверждённые новые заказы']];return `${pageHead('ВЫХОД ИЗ ЗАСТОЯ','Работа и продажи','Здесь важны не дизайны, исследования и идеи, а настоящие контакты, диалоги и оплаты.',`<button class="button" data-page="ideas">Банк идей ${icon('arrow')}</button>`)}<section class="card focus-feature"><div class="eyebrow">ОДНА АКТИВНАЯ ГИПОТЕЗА</div><h2 class="mt8">${e(state.profile?.focus_title||'Проверить спрос на одну услугу')}</h2><p class="small muted mt8">Не меняй направление из-за скуки на третий день. Проверь его реальными разговорами и платежами.</p></section><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Сегодняшняя воронка</h2><span class="pill gray">${ruDate(today())}</span></div><form class="stack" data-form="sales"><div class="form-grid">${field('sales_contacts','Кому написал','number',t.sales_contacts??0,'required min="0" max="10000" step="1"')}${field('sales_replies','Ответили','number',t.sales_replies??0,'required min="0" max="10000" step="1"')}${field('sales_calls','Разговоры','number',t.sales_calls??0,'required min="0" max="10000" step="1"')}${field('sales_offers','Отправил предложения','number',t.sales_offers??0,'required min="0" max="10000" step="1"')}${field('sales_paid','Новых оплаченных заказов','number',t.sales_paid??0,'required min="0" max="10000" step="1"')}</div><button type="submit" class="button">Сохранить результаты</button></form><p class="footnote mt14">Это действия и количество заказов. Суммы фактически полученных денег записывай в разделе «Финансы».</p></section><section class="card"><div class="card-header"><h2>Воронка · 30 дней</h2><span class="pill gray">${recorded}/30 дней с данными</span></div>${cells.map((x,i)=>`<div class="funnel-row"><div class="spread"><span class="small muted">${e(x[0])}</span><b>${x[1]}</b></div><div class="progress-track"><div class="progress-fill" style="width:${s.contacts?clamp(x[1]/s.contacts*100):0}%"></div></div></div>`).join('')}<div class="insight-strip mt20">${e(growthAdvice())}</div><p class="footnote mt14">Показатели этапов могут относиться к разным клиентам и дням, поэтому их нельзя считать точной конверсией одного потока.</p></section></div><section class="card mt20"><div class="card-header"><h2>Контакты с клиентами · 30 дней</h2><span class="pill gray">Цель: 8 контактов в рабочий день</span></div>${svgChart(logs.map(d=>state.data.daily_logs.find(x=>x.log_date===d)?.sales_contacts??null),logs.map(d=>d.slice(8)),{target:8})}<p class="small muted mt14">За последние 7 дней: ${n.contacts} контактов, ${n.replies} ответов и ${n.paid} оплат. Проверяй закономерности, не делай выводов по двум сообщениям.</p></section>`}
function renderGrowthPanel(){const g=growthSignals();return `<div class="grid cols2 mt20"><section class="card growth-card"><div class="spread"><div><div class="eyebrow">GROWTH INDEX · 7 ДНЕЙ</div><h2 class="mt8">Ритм реальных действий</h2></div><span class="pill gray">${g.coverage}/7 записей</span></div><div class="growth-hero"><strong>${g.score===null?'—':g.score+' / 100'}</strong><span>${g.score===null?'Недостаточно данных':'Процессы, не результаты'}</span></div>${g.signals.map(x=>`<div class="growth-row"><div class="spread"><span>${e(x.name)}</span><b>${Math.round(x.value)}%</b></div><div class="progress-track"><div class="progress-fill" style="width:${x.value}%"></div></div><div class="footnote">${e(x.detail)}</div></div>`).join('')}<p class="footnote mt14">${e(g.reason)}</p></section><section class="card growth-card"><div class="eyebrow">ДИАГНОСТИКА БЕЗ САМООБМАНА</div><h2 class="mt8">Что тормозит результат?</h2><div class="growth-advice mt20">${icon('spark')} <div>${e(growthAdvice())}</div></div><div class="insight-strip mt20">Большой доход — результат, а не галочка. Сначала создавай воспроизводимый процесс продаж.</div><button class="button secondary mt20" data-page="sales">Посмотреть воронку продаж ${icon('arrow')}</button><div class="gentle-note mt14">На тяжёлый день: один адресный контакт, 10 минут английского и короткая прогулка — тоже возвращение к маршруту.</div></section></div>`}
function renderDashboard(){
 const d=today(),log=state.data.daily_logs.find(x=>x.log_date===d)||{},tasks=(state.data.tasks||[]).filter(t=>(t.task_date===d)&&!['cancelled','skipped'].includes(t.status));
 const complete=tasks.filter(taskIsDone).length,open=tasks.filter(t=>!taskIsDone(t));
 const top=open.find(t=>t.is_main)||open[0],income=monthIncome(),debt=currentDebt(),reflected=Boolean(log.reflection_done),st=weekStats();
 const daysSince=deltaDays(state.profile?.started_at||d,d)+1;
 const seven=lastDays(7).map(x=>{const l=state.data.daily_logs.find(y=>y.log_date===x)||{};const tt=state.data.tasks.filter(t=>t.task_date===x);return {day:x,completed:tt.filter(taskIsDone).length,reflection:Boolean(l.reflection_done),planned:tt.length}});
 const pct=tasks.length?Math.round(100*complete/tasks.length):null;
 const incomeGoal=num(state.profile?.goal_90)||1500;
 const focusLabel=top?.title||'Пока нет главного шага';
 const recent=(state.data.experiments||[]).filter(x=>x.status==='testing').length;
 return `<div class="mb7-home">
 <section class="mb7-hero" style="--hero-image:url('./mountain-hero.webp')"><div class="mb7-hero-body"><span class="mb7-eyebrow">ТВОЯ ЭКСПЕДИЦИЯ · ДЕНЬ ${daysSince}</span><h1>К вершине<br>один шаг за раз.</h1><p>Сегодня не нужно менять всю жизнь. Достаточно сделать то, что действительно важно.</p><button data-page="route" class="mb7-hero-link">Моя вершина ${icon('arrow')}</button></div></section>
 <div class="mb7-section-heading"><div><span class="mb7-eyebrow">${e(ruDate(d))}</span><h2>Сегодня</h2></div><button data-page="tasks" class="mb7-text-link">Все задачи ${icon('arrow')}</button></div>
 <section class="mb7-panel mb7-focus"><div class="mb7-focus-top"><span class="mb7-dot"></span><span>ГЛАВНЫЙ ШАГ</span><span class="mb7-focus-progress">${tasks.length?`${complete} из ${tasks.length}`:'Без плана'}</span></div>
 <div class="mb7-focus-row"><button ${top?`data-action="toggle-task" data-id="${e(top.id)}"`: 'data-action="new-task"'} class="mb7-focus-check" aria-label="${top?'Отметить главное действие выполненным':'Создать главное действие'}">${icon(top?'check':'plus')}</button><div><strong>${e(focusLabel)}</strong><small>${top?'Одно конкретное действие приближает к цели':'Добавь важную задачу на сегодня'}</small></div></div>
 <div class="mb7-meter" aria-label="Выполнено ${pct===null?0:pct}%"><span style="width:${pct||0}%"></span></div><div class="mb7-focus-bottom"><span>${pct===null?'Поставь первый ориентир':`Выполнено ${pct}%`}</span><button data-page="tasks">Открыть план ${icon('arrow')}</button></div></section>
 <div class="mb7-quick-grid"><button class="mb7-quick" data-page="reflection"><span class="mb7-quick-icon violet">${icon('journal')}</span><strong>Мой дневник</strong><small>${reflected?'Записан сегодня':'Мысли, энергия, выводы'}</small><span class="mb7-quick-right">${reflected?'✓':'›'}</span></button><button class="mb7-quick" data-page="ideas-hub"><span class="mb7-quick-icon amber">${icon('compass')}</span><strong>Поиск дохода</strong><small>${recent?'Проверок в работе: '+recent:'Проверяй идеи на практике'}</small><span class="mb7-quick-right">›</span></button></div>
 ${evolutionHomeCard()}<div class="mb7-section-heading mb7-section-gap"><div><span class="mb7-eyebrow">ПРОГРЕСС ПО ФАКТАМ</span><h2>Мои показатели</h2></div><button class="mb7-text-link" data-page="more">Все разделы ${icon('arrow')}</button></div>
 <div class="mb7-metrics"><button data-page="finance" class="mb7-metric"><span class="mb7-metric-icon blue">${icon('wallet')}</span><span class="mb7-metric-label">Доход за месяц</span><strong>${money(income)}</strong><small>Цель: ${money(incomeGoal)}</small></button><button data-page="finance" class="mb7-metric"><span class="mb7-metric-icon coral">${icon('target')}</span><span class="mb7-metric-label">Текущий долг</span><strong>${money(debt)}</strong><small>К снижению</small></button><button data-page="reflection" class="mb7-metric"><span class="mb7-metric-icon mint">${icon('heart')}</span><span class="mb7-metric-label">Энергия сегодня</span><strong>${log.evening_energy??(log.energy!=null?normalizedEnergy(log):'—')}<em>${log.evening_energy!=null||log.energy!=null?'/10':''}</em></strong><small>${log.evening_energy!=null||log.energy!=null?'Отмечено':'Пока не записана'}</small></button><button data-page="english" class="mb7-metric"><span class="mb7-metric-icon lavender">${icon('book')}</span><span class="mb7-metric-label">Английский · 7 дней</span><strong>${st.english}<em> мин</em></strong><small>Практика за неделю</small></button></div>
 <section class="mb7-panel mb7-goals-preview"><div class="mb7-section-heading"><div><span class="mb7-eyebrow">ЦЕЛИ И РЕЗУЛЬТАТЫ</span><h2>Карта целей</h2></div><button data-page="route" class="mb7-text-link">Все цели ${icon('arrow')}</button></div>${state.data.goals.length?`<div class="mb7-goals-list">${goalCards(state.data.goals.slice(0,2))}</div>`:emptyMessage('Пока нет целей','Создай измеримую цель и следующий шаг',`<button data-action="new-goal" class="button">Добавить цель</button>`)}</section><section class="mb7-panel mb7-weekly"><div class="mb7-section-heading"><div><span class="mb7-eyebrow">ПРОГРЕСС НЕ ЗА ОДИН ДЕНЬ</span><h2>Моя неделя</h2></div><button data-page="route" class="mb7-text-link">Отчёт ${icon('arrow')}</button></div><div class="mb7-week-dots">${seven.map((x,i)=>`<button data-page="progress" title="${e(ruDate(x.day))}" class="mb7-week-day"><span>${['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][new Date(x.day+'T12:00:00').getDay()]}</span><i class="${x.reflection?'has-reflection':x.completed?'has-work':''} ${x.day===d?'is-today':''}">${x.reflection?'✓':x.completed?'•':''}</i></button>`).join('')}</div><div class="mb7-week-legend"><span><i class="success"></i> Итог дня</span><span><i class="doing"></i> Выполненное</span></div></section>
 <button data-page="feed" class="mb7-bottom-call"><span>${icon('journal')}</span><span><strong>Моя история</strong><small>Задачи, мысли и шаги — в одной ленте</small></span>${icon('arrow')}</button>
 <div class="mb7-foot-note">Самое главное — не количество отметок, а действия, которые меняют твою жизнь.</div>
 </div>`;
}

function renderToday(){const log=state.data.daily_logs.find(x=>x.log_date===today())||{};const st=weekStats();return `${renderTodayLinks()}${pageHead('Точка действия','Сегодня — один понятный шаг.','Сначала главное действие для дохода. Затем здоровье, язык и время с семьёй.',`<button class="button" data-action="new-task">${icon('plus')} Задача</button>`)}<div class="grid cols2"><section class="card highlight"><div class="spread mb14"><h2>${state.lowEnergy?'Минимум на сложный день':'Три главных действия'}</h2><button class="button small ghost" data-action="low-energy">${state.lowEnergy?'Обычный режим':'Мало энергии?'}</button></div>${state.lowEnergy?`<div class="low-energy-card"><b>10 минут. Один шаг.</b><p>Напиши одному потенциальному клиенту или сделай первый маленький шаг. Это не заменяет полноценные цели, но помогает вернуться к действию.</p></div>`:todayTasks()}<button class="button secondary small mt14" data-action="new-task">Добавить следующее действие</button><div class="callout subtle-callout mt20">В день с низкой энергией достаточно одного короткого действия на 10 минут. Никаких штрафов за отсутствие идеальной серии.</div></section><section class="card"><div class="card-header"><h2>Короткий чек-ин</h2><span class="pill gray">${ruDate(today())}</span></div><form data-form="daily" class="stack"><div class="form-grid">${field('sleep_hours','Сон, часов','number',log.sleep_hours??'','min="0" max="24" step="0.1"')}${selectField('energy','Энергия (1–10)',[...Array(10)].map((_,i)=>[i+1,`${i+1}/10`]),String(normalizedEnergy(log)||6))}${field('focus_min','Сосредоточенная работа, мин','number',log.focus_min??0,'min="0" max="1440"')}${field('social_min','Соцсети, мин','number',log.social_min??0,'min="0" max="1440"')}${field('exercise_min','Спорт / движение, мин','number',log.exercise_min??0,'min="0" max="1440"')}${field('english_min','Английский, мин · цель 60','number',log.english_min??0,'min="0" max="1440"')}${field('learning_min','Видео или книга, мин · цель 60','number',log.learning_min??0,'min="0" max="1440"')}${selectField('learning_kind','Формат обучения',[['video','Видео / курс'],['book','Книга / аудиокнига'],['practice','Практика / конспект']],log.learning_kind||'video')}${field('family_min','Качественное время с семьёй, мин','number',log.family_min??0,'min="0" max="1440"')}${selectField('mood','Настроение',[['1','1 · тяжело'],['2','2 · ниже среднего'],['3','3 · нормально'],['4','4 · хорошо'],['5','5 · отлично']],String(log.mood||3))}</div>${field('learning_title','Что изучал? Название / глава','text',log.learning_title||'','placeholder="Например: книга, глава 3"')}${field('learning_insight','Одно применимое знание','textarea',log.learning_insight||'','placeholder="Что я изменю на практике?"')}${field('one_action','Что сегодня приблизило к цели?','textarea',log.one_action||'','placeholder="Даже маленькое конкретное действие"')}${field('obstacle','Что мешало?','textarea',log.obstacle||'','placeholder="Без самообвинений: наблюдение → корректировка"')}<button class="button" type="submit">${icon('check')} Сохранить день</button></form></section></div><section class="card mt20"><div class="card-header"><h2>Твой текущий ритм</h2><span class="pill gray">7 дней</span></div><div class="grid cols4">${kpi('Дней с записью',String(st.logs),'из последних семи','calendar')}${kpi('Работа в фокусе',String(st.focus)+' мин','за неделю','sun')}${kpi('Английский',String(st.english)+' мин','за неделю','book')}${kpi('Время с семьёй',String(st.family)+' мин','за неделю','users')}</div></section>`}
function renderGoals(){const gs=[...state.data.goals].sort((a,b)=>String(a.deadline||'9999').localeCompare(String(b.deadline||'9999')));const buckets=[['90','Ближайшие 90 дней','Измеримые результаты, которые влияют на каждую неделю'],['year','Горизонт 12 месяцев','Стабильность вместо хаотичных рывков'],['long','Долгосрочная карта','Большие мечты, не ежедневное давление']];return `${pageHead('От мечты к действию','Твоя карта целей','Для каждой цели есть исходная точка, числовой ориентир, срок и следующий шаг.',`<button class="button" data-action="new-goal">${icon('plus')} Добавить цель</button>`)}<div class="card highlight mb14"><div class="spread"><div><div class="eyebrow">Фокус этой недели</div><h2 class="mt8">${e(state.profile?.focus_title||'Проверить спрос и получить первый заказ')}</h2></div><span class="pill">Один проект за раз</span></div></div><div class="card mt20 roadmap-card"><div class="card-header"><div><div class="eyebrow">ДОРОЖНАЯ КАРТА · ДО 90 ДНЕЙ</div><h2 class="mt8">Промежуточные контрольные точки</h2></div><span class="pill gray">Это ориентиры, не автоматические достижения</span></div><div class="roadmap-grid">${[['Дни 1–14','Одна услуга','Выбрать конкретную аудиторию, написать предложение, получить первые ответы'],['Дни 15–30','Первый клиент','Дойти до разговоров с покупателями и первого оплаченного теста'],['Дни 31–60','Повторяемость','Повторять рабочий сценарий продаж, выйти на €500–1 000/мес'],['Дни 61–90','€1 500 / мес','Получать заказы по повторяемой схеме и вести учёт оплаты']].map(([time,label,detail],i)=>`<div class="roadmap-stop"><div class="roadmap-num">0${i+1}</div><div class="micro muted">${time}</div><h3 class="mt8">${label}</h3><p>${detail}</p></div>`).join('')}</div><p class="footnote mt14">Прохождение 14 или 30 дней само по себе не означает выполнение этапа — отмечай факты и проверяй оплаты.</p></div>${buckets.map(([h,title,sub])=>`<h2 class="section-title">${title}</h2><p class="muted small mb14">${sub}</p><div class="grid cols2">${gs.filter(g=>g.horizon===h).length?gs.filter(g=>g.horizon===h).map(g=>`<div class="card soft">${goalCards([g])}</div>`).join(''):'<div class="card"><div class="empty">Здесь пока нет активных целей.</div></div>'}</div>`).join('')}<div class="card mt20"><div class="card-header"><h2>Как мы измеряем прогресс</h2></div><div class="grid cols3"><div><span class="pill">Результат</span><p class="small muted mt8">Доход, долг, количество оплаченных заказов</p></div><div><span class="pill gray">Действия</span><p class="small muted mt8">Контакты с клиентами, практика английского, тренировки</p></div><div><span class="pill gold">Качество жизни</span><p class="small muted mt8">Энергия, сон, время с семьёй, отсутствие перегруза</p></div></div></div>`}
function renderFinance(){const arr=[...state.data.finance_entries].sort((a,b)=>String(b.entry_date).localeCompare(String(a.entry_date)));const mo=monthKey(today()),income=monthIncome(mo),expense=arr.filter(x=>x.kind==='expense'&&monthKey(x.entry_date)===mo).reduce((s,x)=>s+num(x.amount_eur),0),repay=arr.filter(x=>x.kind==='debt_payment'&&monthKey(x.entry_date)===mo).reduce((s,x)=>s+num(x.amount_eur),0);return `${pageHead('Деньги без иллюзий','Финансовая панель','Фактические поступления, расходы, долг и платежи — отдельно от планов.',`<button class="button" data-action="new-finance">${icon('plus')} Добавить операцию</button>`)}<div class="grid cols4">${kpi('Доход за месяц',money(income),'Только подтверждённые поступления','wallet','accent')}${kpi('Расходы за месяц',money(expense),'Внесённые расходы','wallet')}${kpi('Текущий долг',money(currentDebt()),'Баланс по последнему снимку','target','warn')}${kpi('Резерв 20%',money(monthReserve()),`Нужно перевести ${money(income*.2)} · реально ${money(monthReserve())}`,'check')}</div><div class="card reserve-feature mt20"><div class="spread"><div><div class="eyebrow">ПРАВИЛО ФИНАНСОВОЙ ЗАЩИТЫ</div><h2 class="mt8">20% каждого поступления — на отдельный резервный счёт</h2><p class="small muted mt8">План за месяц: <b>${money(income*.2)}</b> · отмечено переводов: <b>${money(monthReserve())}</b> · накоплено по записям: <b>${money(reserveBalance())}</b></p></div><div class="reserve-mark">20%</div></div><div class="progress-track mt14"><div class="progress-fill" style="width:${income>0?clamp(monthReserve()/(income*.2)*100):0}%"></div></div><p class="footnote mt14">MONTBLANC рассчитывает сумму и отмечает перевод, но не отправляет деньги в банк. При нехватке средств на необходимые расходы семьи лучше пересмотреть доступную сумму, чем накапливать дорогие просрочки.</p></div><div class="grid cols2 mt20"><div class="card"><div class="card-header"><h2>Доход · последние 6 месяцев</h2><span class="pill gray">Цель: ${money(state.profile?.goal_90||1500)}</span></div>${incomeChart()}</div><div class="card"><div class="card-header"><h2>Финансовые этапы</h2></div><div class="timeline">${[['01','Первый платёж'],['02','€500/мес'],['03','€1 500/мес'],['04','€2 500/мес']].map(([n,label])=>`<div class="timeline-item"><div class="timeline-circle">${n}</div><div class="micro muted">${e(label)}</div></div>`).join('')}</div><hr class="divider"/><div class="callout subtle-callout">Долг уменьшается в аналитике только после записи фактического остатка. Одни лишь платежи не гарантируют снижение долга: могут быть проценты и комиссии.</div><p class="small muted mt14">Пока неизвестны обязательные расходы семьи и условия кредитов, система не строит фиктивный график полного погашения.</p></div></div><div class="card mt20"><div class="card-header"><h2>Журнал денег</h2><span class="pill gray">${arr.length} записей</span></div>${arr.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Дата</th><th>Тип</th><th>Сумма</th><th>Комментарий</th><th></th></tr></thead><tbody>${arr.map(x=>`<tr><td>${ruDate(x.entry_date)}</td><td>${e(({income:'Доход',expense:'Расход',debt_balance:'Остаток долга',debt_payment:'Платёж по долгу'})[x.kind]||x.kind)}</td><td>${money(x.amount_eur)}</td><td>${e(x.description||'—')}</td><td><button class="button small ghost" data-action="delete" data-table="finance_entries" data-id="${e(x.id)}">Удалить</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Записей ещё нет. Начни с первого фактического поступления или обновления остатка долга.</div>'}</div>`}
function renderHabits(){const logs=state.data.daily_logs;const labels=lastDays(14);const st=weekStats();const graph=(key)=>svgChart(labels.map(d=>logs.find(x=>x.log_date===d)?.[key]??null),labels.map(d=>d.slice(8)),{target:key==='social_min'?60:null});return `${pageHead('Энергия — ресурс','Здоровье и привычки','Сон, тело, фокус и экранное время. Мягкий контроль без наказаний.',`<button class="button" data-page="reflection">${icon('plus')} Заполнить сегодняшний день</button>`)}<div class="grid cols4">${kpi('Сон за 7 дней',st.sleepAverage===null?'—':st.sleepAverage.toFixed(1)+' ч','Среднее только по записям','heart')}${kpi('Энергия',st.energyAverage===null?'—':st.energyAverage.toFixed(1)+'/5','Самооценка, не диагноз','sun')}${kpi('Тренировок',String(st.sport),'Ориентир: 3 в неделю','heart')}${kpi('Соцсети',st.socialAverage===null?'—':st.socialAverage+' мин','Ориентир: ≤60 минут в день','chart')}</div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Время в соцсетях</h2><span class="pill gray">14 дней</span></div>${graph('social_min')}</section><section class="card"><div class="card-header"><h2>Сосредоточенная работа</h2><span class="pill gray">14 дней</span></div>${graph('focus_min')}</section><section class="card"><div class="card-header"><h2>Сон</h2><span class="pill gray">14 дней</span></div>${svgChart(labels.map(d=>logs.find(x=>x.log_date===d)?.sleep_hours??null),labels.map(d=>d.slice(8)),{target:7})}</section><section class="card"><div class="card-header"><h2>Энергия (1–5)</h2><span class="pill gray">14 дней</span></div>${svgChart(labels.map(d=>normalizedEnergy(logs.find(x=>x.log_date===d))),labels.map(d=>d.slice(8)),{max:5})}</section></div><div class="card mt20"><div class="card-header"><h2>Привычки, которые работают на тебя</h2></div><div class="grid cols3"><div><div class="eyebrow">Тело</div><h3 class="mt8">3 тренировки в неделю</h3><p class="small muted mt8">Начать с посильных 20–40 минут. Увеличивать нагрузку постепенно.</p></div><div><div class="eyebrow">Английский</div><h3 class="mt8">20 минут ежедневно</h3><p class="small muted mt8">Регулярная практика важнее попытки каждый раз заниматься идеально.</p></div><div><div class="eyebrow">Семья</div><h3 class="mt8">Время без экрана</h3><p class="small muted mt8">Короткое осознанное общение каждый день, без превращения семьи в KPI.</p></div></div></div>`}
function renderIdeas(){const ideas=[...state.data.ideas].sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)));const filtered=state.filter==='all'?ideas:ideas.filter(x=>x.status===state.filter);return `${pageHead('Парковка идей','Идеи — не обязательства.','Записывай, комментируй и оценивай. Новая идея не отменяет выбранный 14-дневный фокус.',`<button class="button" data-action="new-idea">${icon('plus')} Записать идею</button>`)}<div class="card highlight mb14"><div class="spread"><div><h2>Правило: одна активная проверка</h2><p class="small muted mt8">Остальные идеи лежат здесь до еженедельного обзора.</p></div><span class="pill">Без переключений</span></div></div><div class="seg mb14" style="width:max-content;max-width:100%;overflow:auto">${[['all','Все'],['inbox','Новые'],['analysis','Анализ'],['testing','Тестирую'],['project','Проекты'],['parked','Позже'],['discarded','Архив']].map(([v,t])=>`<button class="${state.filter===v?'selected':''}" data-action="filter-ideas" data-value="${v}">${t}</button>`).join('')}</div><div class="grid cols2">${filtered.length?filtered.map(x=>{const ct=state.data.idea_comments.filter(z=>z.idea_id===x.id).length;return `<div class="idea-card"><div class="spread"><span class="pill ${x.status==='testing'?'':'gray'}">${e(({inbox:'Новая',analysis:'На анализе',testing:'На проверке',project:'Проект',parked:'В запасе',discarded:'Архив'})[x.status]||x.status)}</span><span class="small muted">${ruDate((x.created_at||'').slice(0,10))}</span></div><h3>${e(x.title)}</h3><p>${e(x.description||'Без описания').slice(0,200)}${String(x.description||'').length>200?'…':''}</p><div class="spread mt14"><span class="small muted">${ct} комментариев</span><button class="button small secondary" data-action="view-idea" data-id="${e(x.id)}">Открыть ${icon('arrow')}</button></div></div>`}).join(''):'<div class="empty">Пока нет идей в этом разделе.</div>'}</div>`}
function renderJournal(){const entries=[...state.data.journal_entries].sort((a,b)=>String(b.entry_date).localeCompare(String(a.entry_date)));return `${pageHead('Мысли и наблюдения','Личный дневник','Фиксируй опыт, решения, сомнения и то, что реально сработало.',`<button class="button" data-action="new-journal">${icon('plus')} Новая запись</button>`)}<div class="grid cols2"><section class="card highlight"><h2 class="mb14">О чём стоит написать сегодня</h2><div class="plan-step"><span class="step-number">1</span><div><h3>Что сегодня получилось?</h3><p>Даже одно маленькое полезное действие.</p></div></div><div class="plan-step"><span class="step-number">2</span><div><h3>Где я потерял время или энергию?</h3><p>Описать причину, а не критиковать себя.</p></div></div><div class="plan-step"><span class="step-number">3</span><div><h3>Что я сделаю завтра иначе?</h3><p>Один конкретный эксперимент вместо списка обещаний.</p></div></div></section><section class="card"><div class="card-header"><h2>История записей</h2><span class="pill gray">${entries.length}</span></div>${entries.length?entries.map(x=>`<div class="journal-item"><div class="small muted">${ruDate(x.entry_date)}</div><h3>${e(x.title||'Запись')}</h3><p>${e(x.content||'')}</p><div class="row mt8"><button class="button small ghost" data-action="edit-journal" data-id="${e(x.id)}">Изменить</button><button class="button small ghost" data-action="delete" data-table="journal_entries" data-id="${e(x.id)}">Удалить</button></div></div>`).join(''):'<div class="empty">Первая запись появится здесь. Не обязательно писать каждый день.</div>'}</section></div>`}
function renderReview(){const st=weekStats(),todayLog=state.data.daily_logs.find(x=>x.log_date===today());const recent=state.data.weekly_reviews.slice().sort((a,b)=>String(b.week_end).localeCompare(String(a.week_end)));const weekStart=plusDays(today(),-6);const review=recent.find(x=>x.week_end===today())||{};return `${pageHead('Результаты вместо эмоций','Недельный обзор','Раз в неделю смотри на действия, деньги и самочувствие — затем корректируй следующий шаг.',`<button class="button" data-page="reflection">${icon('sun')} Перейти к сегодняшнему дню</button>`)}<div class="grid cols4">${kpi('Заполнено дней',`${st.logs}/7`,'Регулярность наблюдений','calendar')}${kpi('Выполнено задач',String(st.completed),'За последние 7 дней','check')}${kpi('Фокус',`${st.focus} мин`,'Сосредоточенная работа','target')}${kpi('Тренировки',String(st.sport),'Длительностью ≥20 минут','heart')}</div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Результат и выводы</h2><span class="pill gray">${ruDate(weekStart)} — ${ruDate(today())}</span></div><form data-form="review" class="stack">${field('wins','3 факта, которые показывают прогресс','textarea',review.wins||'','placeholder="Конкретные действия или результаты"')}${field('blockers','Что мешало на этой неделе?','textarea',review.blockers||'','placeholder="Например: работа без продаж, соцсети, нерегулярный сон"')}${field('adjustment','Что меняю на следующей неделе?','textarea',review.adjustment||'','placeholder="Одно изменение, которое можно проверить"')}${field('next_week_focus','Главный фокус на следующую неделю','textarea',review.next_week_focus||'','placeholder="Только один главный приоритет"')}<button class="button" type="submit">${icon('check')} Сохранить недельный разбор</button></form></section><section class="card"><div class="card-header"><h2>Дневные записи за 7 дней</h2></div>${lastDays(7).map(d=>{const l=state.data.daily_logs.find(x=>x.log_date===d);return `<div class="spread" style="border-top:1px solid var(--edge);padding:14px 0"><span class="small">${ruDate(d)}</span><div class="row"><span class="pill gray">${l?'Фокус '+num(l.focus_min)+' мин':'Нет записи'}</span><span class="pill ${l&&num(l.energy)>=4?'':'gray'}">${l?'Энергия '+num(l.energy)+'/5':'—'}</span></div></div>`}).join('')}<div class="callout subtle-callout mt14">Если неделя была сложной, цель — не «догонять», а выбрать следующий достижимый шаг. Полезно искать причины, а не виноватых.</div></section></div>${recent.length?`<h2 class="section-title">Архив обзоров</h2><div class="grid cols2">${recent.map(x=>`<div class="card"><div class="small muted">Неделя до ${ruDate(x.week_end)}</div><h3 class="mt8">Что сработало</h3><p class="small note-text mt8">${e(x.wins)}</p><h3 class="mt14">Изменение</h3><p class="small note-text mt8 muted">${e(x.adjustment)}</p></div>`).join('')}</div>`:''}${renderInsights()}`}
function renderGitHubSettings(){return `<hr class="divider"/><h3 class="mt20">🔐 Резервная копия в приватный GitHub</h3><p class="small muted mt8">Все записи шифруются на iPhone и сохраняются в отдельном PRIVATE репозитории. Не подключай публичный репозиторий сайта! Это резервное хранение, а не база в реальном времени. GitHub-ключ приложения сохраняется локально зашифрованным под паролем дневника, но код сайта может получить к нему доступ после разблокировки.</p><div class="safe mt14" id="gh-status">${e(github.status)}${github.repo?' · '+e(github.repo):''}</div><form data-form="github-sync" class="stack mt14"><div class="form-field"><label>Приватный репозиторий GitHub</label><input class="control" name="repo" value="${e(github.repo||'dmitriydizdar2020-cyber/montblanc-private-data')}" placeholder="владелец/название" required /></div><div class="form-field"><label>Fine-grained token · только Contents: Read and write</label><input class="control" name="token" type="password" autocomplete="off" placeholder="${github.token?'Уже подключено — оставь пустым для повторной проверки':'Вставь токен с GitHub'}" /></div><button type="submit" class="button">Подключить приватный архив</button></form><div class="form-actions mt14"><button class="button secondary" data-action="github-backup-now" ${github.token?'':'disabled'}>Сохранить сейчас</button>${github.token?'<button class="button ghost" data-action="github-disconnect">Отключить</button>':''}</div><p class="small muted mt14">После записи архив можно восстановить даже на новом iPhone: на стартовом экране выбери «Восстановить с GitHub». Потребуются токен GitHub и тот же пароль дневника. При потере пароля зашифрованные записи не расшифровать. Если закончится срок действия токена или нет интернета, показывается ошибка; локальные записи продолжают сохраняться.</p>`}
function renderSettingsSummary(p){
 const items=[['Начальный доход',money(p.income_baseline)],['Начальный долг',money(p.debt_baseline)],['Цель на 90 дней',money(p.goal_90)],['Ежемесячный доход через год',money(p.goal_year)],['Доход за 12 месяцев',p.annual_income_goal?money(p.annual_income_goal):'Установить цель'],['Соцсети в начале',(p.social_baseline??0)+' мин/день'],['Спорт в начале',(p.sport_baseline??0)+' раз/нед'],['Главный фокус',p.focus_title||'Пока не выбран'],['Почему хочу измениться',p.why_text||'Не заполнено'],['Жизнь моей мечты',p.vision_text||'Не заполнено']];
 return `<div class="mb7-saved-note"><b>✓ Точка А и цели сохранены</b><small>Значения ниже — сохранённые данные, а не незавершённая форма.</small></div><div class="mb7-saved-fields">${items.map(([title,value])=>`<div class="mb7-saved-field"><span>${e(title)}</span><p>${e(value)}</p></div>`).join('')}</div><button type="button" class="button secondary mt14" data-action="settings-edit">${icon('pencil')} Редактировать точку А</button>`;
}
function renderSettings(){const p=state.profile||{};return `${pageHead('Под твоим контролем','Настройки и приватность','Здесь меняются базовые цифры, фокус и правила хранения данных.')}<div class="grid cols2"><section class="card"><div class="card-header"><h2>Моя точка А и цели</h2></div>${state.settingsEditing?`<form data-form="settings" class="stack"><div class="form-grid">${field('income_baseline','Стабильный доход в начале, €/мес','number',p.income_baseline??0,'min="0" step="0.01" required')}${field('debt_baseline','Долг в начале, €','number',p.debt_baseline??0,'min="0" step="0.01" required')}${field('goal_90','Цель через 90 дней, €/мес','number',p.goal_90??1500,'min="0" required')}${field('goal_year','Ежемесячный доход через 12 месяцев, €/мес','number',p.goal_year??2500,'min="0" required')}${field('annual_income_goal','Доход за 12 месяцев, € (НЕ в месяц)','number',p.annual_income_goal??15000,'min="0" step="100" required')}${field('social_baseline','Соцсети в начале, мин/день','number',p.social_baseline??120,'min="0" required')}${field('sport_baseline','Спорт в начале, раз/нед','number',p.sport_baseline??1,'min="0" required')}</div>${field('focus_title','Один главный фокус на ближайшие 14 дней','textarea',p.focus_title||'')}${field('why_text','Моя причина двигаться вперёд','textarea',p.why_text||'')}${field('vision_text','Жизнь, которую хочу построить','textarea',p.vision_text||'')}<button class="button" type="submit">${icon('check')} Сохранить настройки</button></form>`:renderSettingsSummary(p)}</section><section class="card"><div class="card-header"><h2>Доступ и данные</h2><span class="pill">${state.demo?'DEMO':icon('lock')+' PRIVATE'}</span></div><div class="safe">${state.demo?'Это демонстрационный режим. Записи исчезнут после перезагрузки.':state.local?'🔒 Записи зашифрованы на этом устройстве. Можно подключить приватный GitHub-архив для восстановления после переустановки.':'Личные записи в Supabase защищены авторизацией и RLS.'}</div>${state.local?`<div class="mb7-trusted-device"><h3 class="mt20">Вход на этом iPhone</h3><p class="small muted mt8">${rememberedDevice?'Быстрый вход включён. После закрытия приложения пароль не нужен.':'Можно запомнить этот iPhone, чтобы не вводить пароль при каждом запуске.'} На устройстве сохраняется локальный криптографический ключ, доступный коду сайта. Если кто-то получит доступ к разблокированному телефону, записи станут доступнее. Пароль всё равно нужен для восстановления из GitHub.</p><button class="button secondary mt14" data-action="device-trust-toggle">${rememberedDevice?'Отключить быстрый вход':'Запомнить этот iPhone'}</button></div>`:''}${state.local?renderGitHubSettings():''}<h3 class="mt20">Резервная копия</h3><p class="small muted mt8">${state.local?'Скачай зашифрованный архив. Для восстановления понадобится пароль.':'Экспорт содержит личные записи без шифрования — храни только в безопасном месте.'}</p><button class="button secondary mt14" data-action="export">${icon('download')} ${state.local?'Скачать шифрованный архив':'Скачать JSON'}</button>${state.local?`<button class="button ghost mt14" data-action="local-lock">${icon('lock')} Заблокировать дневник</button>`:''}<hr class="divider"/><h3 class="mt20">Приложение на телефоне</h3><p class="small muted mt8">На iPhone: открой опубликованную HTTPS-ссылку в Safari → Поделиться → На экран «Домой». На Android: нажми кнопку ниже или используй меню Chrome «Установить приложение».</p><button class="button secondary mt14" data-action="install-app">${icon('download')} Установить на устройство</button><p class="small muted mt8">Для установки нужен опубликованный HTTPS-адрес. Локальный HTML-файл не устанавливается как PWA. Offline-доступ сохраняет только код приложения; личные записи хранятся отдельно в локальном зашифрованном хранилище или защищённой базе.</p><h3 class="mt20">Важная граница приватности</h3><p class="small muted mt8">Публикуемый веб-интерфейс может быть открыт для просмотра до входа. В локальном режиме записи шифруются на устройстве; в облачном — защищаются авторизацией и RLS. Страница входа может быть публичной, хотя записи закрыты.</p><hr class="divider"/>${state.demo?`<button class="button ghost" data-action="leave-demo">Выйти из демо</button>`:`<button class="button ghost" data-action="logout">${icon('logout')} Выйти из аккаунта</button>`}</section></div>`}
function renderLearning(){const logs=logBetween(plusDays(today(),-29),today()),days=lastDays(30),total=sumOf(logs,'learning_min'),hits=logs.filter(x=>num(x.learning_min)>=60).length,books=logs.filter(x=>x.learning_kind==='book'),vid=logs.filter(x=>x.learning_kind==='video'),notes=logs.filter(x=>String(x.learning_title||'').trim());return `${pageHead('60 МИНУТ КАЖДЫЙ ДЕНЬ','Знания, которые меняют действия.','Книга, лекция, курс или практическое видео. Каждый день записывай одну применимую мысль.',`<button class="button" data-page="reflection">Записать обучение ${icon('plus')}</button>`)}<section class="learning-hero"><div><div class="eyebrow">ИНТЕЛЛЕКТУАЛЬНЫЙ КАПИТАЛ</div><h2 class="mt8">1 час в день × 30 дней = 30 часов осознанного обучения.</h2><p>Важно не просто смотреть и читать, а фиксировать один вывод, который применишь завтра.</p></div>${ring(clamp(total/(30*60)*100),'',''+Math.round(total/60*10)/10+' ч',{size:150,color:'#856af4'})}</section><div class="grid cols4 mt20">${kpi('Часы за 30 дней',(total/60).toFixed(1),'План: 30 часов','book')}${kpi('Дней ≥60 минут',String(hits),'За последние 30 дней','check')}${kpi('Книги / чтение',String(books.length),'Дневных записей','book')}${kpi('Видео / курсы',String(vid.length),'Дневных записей','chart')}</div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Обучение · последние 30 дней</h2><span class="pill gray">Пунктир — 60 мин</span></div>${svgChart(days.map(d=>logs.find(l=>l.log_date===d)?.learning_min??null),days.map(d=>d.slice(5)),{target:60})}</section><section class="card"><div class="card-header"><h2>Принцип 60 / 10</h2><span class="pill gray">Практика важнее количества</span></div><div class="plan-step"><span class="step-number">01</span><div><h3>Выбери один материал</h3><p>Книга или видео на тему, полезную для твоих целей.</p></div></div><div class="plan-step"><span class="step-number">02</span><div><h3>60 минут без переключений</h3><p>Только этот материал, телефон вне зоны внимания.</p></div></div><div class="plan-step"><span class="step-number">03</span><div><h3>10 минут на применение</h3><p>Запиши один вывод и используй в течение суток.</p></div></div></section></div><div class="card mt20"><div class="card-header"><h2>История обучения</h2><span class="pill gray">${notes.length} записей за 30 дней</span></div>${notes.length?notes.sort((a,b)=>b.log_date.localeCompare(a.log_date)).map(l=>`<div class="study-entry"><div class="spread"><strong>${e(l.learning_title)}</strong><span class="small muted">${ruDate(l.log_date)} · ${num(l.learning_min)} мин</span></div><p>${e(l.learning_insight||'Вывод пока не записан')}</p></div>`).join(''):'<div class="empty">Запиши первую книгу или видео в разделе «Сегодня».</div>'}</div>`}
function renderEnglish(){const start=state.profile?.started_at||today(),end=addMonths(start,4),left=Math.max(0,deltaDays(today(),end)),total=Math.max(1,deltaDays(start,end)),daysElapsed=Math.max(0,deltaDays(start,today())),percent=clamp(daysElapsed/total*100),logs=logBetween(plusDays(today(),-29),today()),mins=sumOf(logs,'english_min'),checks=state.data.skill_checks||[],skills=[['speaking','Говорение'],['listening','Аудирование'],['reading','Чтение'],['writing','Письмо']],levels={A1:0,A2:50,B1:100};const lastSkill=s=>checks.filter(x=>x.skill===s).sort((a,b)=>String(b.assessed_on).localeCompare(String(a.assessed_on)))[0];return `${pageHead('ЯЗЫКОВОЙ МАРШРУТ','A1 → B1 за 4 месяца','Амбициозный план. Минуты практики показывают усилия, уровень подтверждаем контрольными заданиями и речью.',`<button class="button" data-action="skill-check">${icon('check')} Отметить проверку</button>`)}<section class="english-hero"><div><div class="eyebrow">ТВОЯ ЦЕЛЬ · B1</div><h2 class="mt8">Говорить увереннее. Понимать больше. Действовать свободнее.</h2><p>Старт A1 · контрольная дата ${ruDate(end)}. До неё ${left} дней; текущий прогресс по календарю ${Math.round(percent)}% — это не оценка языка.</p></div><div class="language-letters">A1 <span>${icon('arrow')}</span> B1</div></section><div class="grid cols4 mt20">${kpi('Практика за 30 дней',(mins/60).toFixed(1)+' ч','План: 30 часов','book')}${kpi('Дней ≥60 мин',String(logs.filter(x=>num(x.english_min)>=60).length),'За 30 дней','check')}${kpi('До контрольной даты',left+' дн','B1 не гарантируется календарём','calendar')}${kpi('Подтверждено B1',String(skills.filter(([k])=>lastSkill(k)?.level==='B1').length)+'/4','Навыка по записанным проверкам','target')}</div><div class="card mt20"><div class="card-header"><h2>4 навыка · только по проверкам</h2><span class="pill gray">Не подменяем уровень часами</span></div><div class="grid cols2">${skills.map(([k,name])=>{const c=lastSkill(k),pct=levels[c?.level]??0;return `<div class="skill-meter"><div class="spread"><strong>${name}</strong><span class="pill gray">${c?e(c.level):'Не проверено'}</span></div><div class="progress-track mt14"><div class="progress-fill" style="width:${pct}%"></div></div><p class="micro muted mt8">${c?`Последняя проверка: ${ruDate(c.assessed_on)} · ${e(c.evidence||'без примера')}`:'Сохрани результат реального занятия или мини-теста'}</p></div>`}).join('')}</div></div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Минуты английского · 30 дней</h2><span class="pill gray">Цель 60 мин/день</span></div>${svgChart(lastDays(30).map(d=>logs.find(x=>x.log_date===d)?.english_min??null),lastDays(30).map(d=>d.slice(5)),{target:60})}</section><section class="card"><div class="card-header"><h2>Маршрут по месяцам</h2><span class="pill gray">Контроль каждые 4 недели</span></div>${[['Месяц 1','A1 → A2','Уверенные базовые фразы, прошедшее и будущее, разговор 3–5 минут'],['Месяц 2','A2','Ежедневные ситуации, аудирование с замедлением, диалог 5–8 минут'],['Месяц 3','A2 → B1','Объяснять мнение, вести разговор 10 минут, понимать адаптированные материалы'],['Месяц 4','Проверка B1','Сдать пробный тест по всем навыкам и разговор 10–15 минут']].map(([m,l,d],i)=>`<div class="plan-step"><span class="step-number">0${i+1}</span><div><div class="small muted">${m} · ориентир</div><h3 class="mt8">${l}</h3><p>${d}</p></div></div>`).join('')}</section></div><div class="card mt20"><h2>Ежедневная практика · 60 минут</h2><div class="grid cols4 mt14">${[['15 мин','Говорить вслух'],['15 мин','Аудирование'],['15 мин','Слова + грамматика'],['15 мин','Чтение или письмо']].map(([n,t])=>`<div class="mini-step"><b>${n}</b><span>${t}</span></div>`).join('')}</div><p class="footnote mt14">Если день тяжёлый, 15–20 минут лучше полного отказа. Для уверенного B1 за четыре месяца обычно требуется и системность, и обратная связь от преподавателя; график не гарантирует результат.</p></div>`}
function selectedMonth(){const d=new Date();d.setDate(1);d.setMonth(d.getMonth()+(state.monthOffset||0));return localDate(d).slice(0,7)}
function monthlyPayload(month){const [yy,mm]=month.split('-').map(Number);const start=`${month}-01`,end=localDate(new Date(yy,mm,0)),logs=logBetween(start,end);const incomes=state.data.finance_entries.filter(x=>x.kind==='income'&&monthKey(x.entry_date)===month);const expenses=state.data.finance_entries.filter(x=>x.kind==='expense'&&monthKey(x.entry_date)===month);const tasks=state.data.tasks.filter(x=>x.task_date>=start&&x.task_date<=end);const daysInMonth=new Date(yy,mm,0).getDate();return {month,days_in_month:daysInMonth,days_elapsed:month===monthKey(today())?Math.min(daysInMonth,Number(today().slice(8))):month<monthKey(today())?daysInMonth:0,days_logged:logs.length,earned_eur:sumOf(incomes,'amount_eur'),income_target_eur:num(state.profile?.goal_90||1500),spending_eur:sumOf(expenses,'amount_eur'),reserve_target_eur:sumOf(incomes,'amount_eur')*.2,reserve_actual_eur:monthReserve(month),debt_snapshot_eur:currentDebt(),study_hours:Math.round(sumOf(logs,'learning_min')/6)/10,english_hours:Math.round(sumOf(logs,'english_min')/6)/10,study_days_60min:logs.filter(l=>num(l.learning_min)>=60).length,english_days_60min:logs.filter(l=>num(l.english_min)>=60).length,exercise_days:logs.filter(l=>num(l.exercise_min)>=20).length,focus_hours:Math.round(sumOf(logs,'focus_min')/6)/10,average_social_minutes:logs.length?Math.round(avg(logs.map(l=>l.social_min))):null,average_energy:logs.some(l=>l.energy!=null)?Math.round(avg(logs.filter(l=>l.energy!=null).map(normalizedEnergy))*10)/10:null,tasks_total:tasks.length,tasks_completed:tasks.filter(t=>t.completed).length,sales_contacts:sumOf(logs,'sales_contacts'),sales_replies:sumOf(logs,'sales_replies'),sales_calls:sumOf(logs,'sales_calls'),sales_offers:sumOf(logs,'sales_offers'),sales_paid:sumOf(logs,'sales_paid'),notes:'Отсутствие записи не означает ноль. Резерв отмечается вручную. Долг — последний снимок, без прогнозирования.'}}
function localAnalysis(r){const n=r.days_logged,coverage=Math.round(n/Math.max(1,r.days_elapsed)*100),a=[];a.push({level:coverage<50?'warn':'good',title:'Качество данных',body:`Заполнено ${n} из ${r.days_elapsed} прошедших дней (${coverage}%). ${coverage<50?'Недостаточно данных для уверенных выводов о привычках.':'Есть база для сравнения привычек.'}`});if(r.earned_eur<r.income_target_eur)a.push({level:'warn',title:'Финансовый результат',body:`Получено ${money(r.earned_eur)} против цели ${money(r.income_target_eur)}. Следующий шаг — измерять контакты, разговоры и оплаченные заказы, не только часы работы.`});else a.push({level:'good',title:'Финансовый результат',body:`Целевой месячный доход достигнут: ${money(r.earned_eur)}. Проверь устойчивость источника и повторяемость заказов.`});if(r.earned_eur>0){a.push({level:r.reserve_actual_eur>=r.reserve_target_eur?'good':'warn',title:'Резерв 20%',body:`План ${money(r.reserve_target_eur)}; внесено ${money(r.reserve_actual_eur)}. ${r.reserve_actual_eur<r.reserve_target_eur?'Проверь возможность перевода с учётом обязательных расходов и долгов.':'План на этот месяц выполнен.'}`})}else a.push({level:'neutral',title:'Резерв 20%',body:'Пока нет записанного дохода. Не считаем отсутствие накоплений провалом.'});if(r.sales_contacts===0)a.push({level:'warn',title:'Воронка продаж',body:'В этом месяце не записано контактов с покупателями. Начни с 5–10 адресных сообщений и фиксируй ответы.'});else if(r.sales_contacts>=20&&r.sales_replies===0)a.push({level:'warn',title:'Низкий отклик',body:`${r.sales_contacts} контактов и 0 ответов по записям. Уточни сегмент и первое сообщение.`});else if(r.sales_replies>=5&&r.sales_offers===0)a.push({level:'warn',title:'От общения к офферу',body:`${r.sales_replies} ответов, но предложений не отмечено. Сформулируй одно конкретное платное предложение.`});else a.push({level:'neutral',title:'Воронка продаж',body:`Контакты ${r.sales_contacts}, ответы ${r.sales_replies}, предложения ${r.sales_offers}, оплаты ${r.sales_paid}. Проверяй, на каком этапе теряются люди.`});a.push({level:r.study_hours>=20?'good':'neutral',title:'Обучение',body:`${r.study_hours} ч за месяц, ${r.study_days_60min} дней с 60+ минутами. Смотри не только часы, но и записанные применённые идеи.`});a.push({level:r.english_hours>=20?'good':'neutral',title:'Английский',body:`${r.english_hours} ч практики. Уровень A1/B1 определяется отдельными проверками речи, чтения, письма и аудирования.`});if(coverage>30&&r.average_social_minutes!==null)a.push({level:r.average_social_minutes<=60?'good':'warn',title:'Время в соцсетях',body:`В записанные дни в среднем ${r.average_social_minutes} мин/день. Попробуй ограничить ленту перед первым рабочим блоком.`});return a}
function renderMonthly(){const m=selectedMonth(),p=monthlyPayload(m),checks=localAnalysis(p),stored=(state.data.ai_reports||[]).filter(x=>x.month_key===m).sort((a,b)=>String(b.created_at).localeCompare(String(a.created_at)))[0];return `${pageHead('РЕЗУЛЬТАТЫ В ЦИФРАХ','Месячный разбор прогресса','Где двигаешься, где отстаёшь и что менять на следующей неделе. Никаких выдуманных оценок.',`<button class="button" data-page="reflection">Заполнить сегодняшний день</button>`)}<div class="month-nav"><button class="button ghost small" data-action="month-prev">← Предыдущий</button><strong>${new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(new Date(m+'-01T12:00:00'))}</strong><button class="button ghost small" data-action="month-next" ${(state.monthOffset||0)>=0?'disabled':''}>Следующий →</button></div><div class="grid cols4 mt20">${kpi('Доход',money(p.earned_eur),`Ориентир ${money(p.income_target_eur)}`,'wallet')}${kpi('Фокус',p.focus_hours+' ч','Глубокая работа','sun')}${kpi('Учёба',p.study_hours+' ч','60 мин ежедневно · цель','book')}${kpi('Английский',p.english_hours+' ч','B1 проверяется отдельно','book')}</div><div class="card mt20"><div class="spread"><h2>Реальные продажи за месяц</h2><span class="pill gray">Контакты → ответы → офферы → оплаты</span></div><div class="sales-kpis">${[['Контакты',p.sales_contacts],['Ответы',p.sales_replies],['Предложения',p.sales_offers],['Оплаты',p.sales_paid]].map(x=>`<div><b>${x[1]}</b><span>${e(x[0])}</span></div>`).join('')}</div><p class="small muted mt8">Зафиксированы действия за ${p.days_logged} дней. Это не подтверждение дохода — денежные поступления учитываются отдельно.</p></div><div class="grid cols2 mt20"><section class="card"><div class="card-header"><h2>Динамика обучения</h2><span class="pill gray">Последние дни месяца</span></div>${(()=>{const [yy,mm]=m.split('-').map(Number);const len=new Date(yy,mm,0).getDate();const dates=Array.from({length:len},(_,i)=>m+'-'+String(i+1).padStart(2,'0'));return svgChart(dates.map(d=>state.data.daily_logs.find(l=>l.log_date===d)?.learning_min??null),dates.map(d=>d.slice(8)),{target:60})})()}</section><section class="card"><div class="card-header"><h2>Честная диагностика</h2><span class="pill gray">${p.days_logged}/${p.days_elapsed} прошедших дней</span></div>${checks.map(c=>`<div class="insight-row ${c.level}"><span class="insight-dot"></span><div><strong>${e(c.title)}</strong><p>${e(c.body)}</p></div></div>`).join('')}</section></div><section class="card mt20 ai-panel"><div class="spread ai-heading"><div><div class="eyebrow">LIFE COACH · CHATGPT</div><h2 class="mt8">Аналитика и план коррекции</h2><p class="small muted mt8">В автономном режиме можно самостоятельно отправить в ChatGPT отчёт после проверки личных заметок.</p></div><span class="ai-star">✦</span></div><div class="row mt20 ai-buttons"><button class="button" data-action="generate-ai" ${(state.demo||state.local)?'disabled title="AI доступен после подключения облачной базы и API"':''}>${icon('spark')} ${stored?'Обновить анализ ChatGPT':'Сформировать анализ ChatGPT'}</button><button class="button secondary" data-action="copy-month">${icon('download')} Скопировать показатели для ChatGPT</button></div><p class="footnote mt14">Ручной анализ доступен по кнопке. Автоматическая рассылка в конце месяца пока не настроена. API OpenAI может оплачиваться отдельно от подписки ChatGPT.</p>${stored?`<div class="ai-report mt20"><div class="small muted">Последний AI-отчёт · ${ruDate((stored.created_at||'').slice(0,10))}</div><p class="report-pre">${e(stored.report_text)}</p></div>`:`<div class="empty mt20">AI-отчёта за выбранный месяц пока нет. Ниже — прозрачная диагностика по правилам, не ответ ИИ.</div>`}</section><div class="card mt20"><h2>План на ближайшие 7 дней</h2><div class="grid cols3 mt14"><div class="mini-step"><b>Доход</b><span>Выбрать одно предложение и сделать реальные контакты с клиентами</span></div><div class="mini-step"><b>Навыки</b><span>60 минут обучения и 60 минут английского в обычный день</span></div><div class="mini-step"><b>Энергия</b><span>3 посильные тренировки и отслеживание сна без самокритики</span></div></div></div>${renderInsights()}`}


/* MONTBLANC 6.0 — expedition, behavioral observations and reflections.
   Existing vault key/version, user records and their original tables stay unchanged.
   New fields remain local-only in encrypted payload; no personal data is published. */
const taskIsDone=t=>Boolean(t.completed)||t.status==='done';
const reasonLabel={time:'Не хватило времени',energy:'Мало энергии',distraction:'Отвлечения и соцсети',uncertainty:'Неясно, с чего начать',overload:'Слишком большая задача',fear:'Страх отказа или ошибки',changed:'Обстоятельства изменились',irrelevant:'Потеряла смысл',other:'Другое'};
const taskLabel={finance:'Доход',health:'Тело',growth:'Развитие',family:'Семья',focus:'Фокус',other:'Личное'};
function normalizedEnergy(log){if(!log||log.energy===undefined||log.energy===null)return null;return log.energy_scale===10?clamp(num(log.energy),1,10):clamp(num(log.energy)*2,1,10)}
function atMonday(date=today()){const d=new Date(`${date}T12:00:00`);const wd=(d.getDay()+6)%7;d.setDate(d.getDate()-wd);return localDate(d)}
function monthEnd(date=today()){const d=new Date(`${date}T12:00:00`);return localDate(new Date(d.getFullYear(),d.getMonth()+1,0,12))}
function taskState(t){return taskIsDone(t)?'done':t.status==='cancelled'?'cancelled':t.status==='skipped'?'skipped':'planned'}
function scopeRange(scope){if(scope==='week')return [atMonday(),plusDays(atMonday(),6)];if(scope==='month')return [today().slice(0,7)+'-01',monthEnd()];return [today(),today()]}
function scopedTasks(scope){const tasks=state.data.tasks||[];const [start,end]=scopeRange(scope);
 let filtered=scope==='all'?tasks:scope==='inbox'?tasks.filter(t=>!t.task_date):scope==='today'?tasks.filter(t=>(t.task_date===today() || (t.task_date&&t.task_date<today()&&!taskIsDone(t)&&!['cancelled','skipped'].includes(t.status)))):tasks.filter(t=>(t.task_date>=start&&t.task_date<=end)||(t.task_date&&t.task_date<start&&!taskIsDone(t)&&!['cancelled','skipped'].includes(t.status)));
 return [...filtered].sort((a,b)=>(taskIsDone(a)?1:0)-(taskIsDone(b)?1:0)||Number(Boolean(b.is_main))-Number(Boolean(a.is_main))||(['high','normal','low'].indexOf(a.priority||'normal')-['high','normal','low'].indexOf(b.priority||'normal'))||String(a.task_date||'9999').localeCompare(String(b.task_date||'9999')));
}
function taskCard(t){const completed=taskIsDone(t),status=taskState(t),muted=['cancelled','skipped'].includes(status),sub=t.subtasks||[];
 return `<article class="mb-task ${completed?'is-done':''} ${muted?'is-muted':''}"><div class="mb-task-row"><button class="mb-task-check ${completed?'checked':''}" data-action="toggle-task" data-id="${e(t.id)}" aria-label="${completed?'Вернуть задачу':'Отметить выполненной'}">${completed?icon('check'):''}</button><div class="mb-task-body"><div class="mb-task-name">${t.is_main?'<span class="priority-star">★ </span>':''}${e(t.title)}</div><div class="mb-task-meta">${e(taskLabel[t.category]||'Другое')} · ${t.task_date?ruDate(t.task_date):'Входящие'}${t.due_time?' · '+e(t.due_time):''}${t.repeat_rule&&t.repeat_rule!=='none'?' · ↻':''}${num(t.deferred_count)>0?` · Переносов: ${num(t.deferred_count)}`:''}</div>${t.notes?`<p class="mb-task-note">${e(t.notes)}</p>`:''}${t.reason&&!completed?`<span class="mb-reason">${e(reasonLabel[t.reason]||'Причина зафиксирована')}</span>`:''}</div><button class="mb-more" data-action="edit-task" data-id="${e(t.id)}" aria-label="Изменить задачу">···</button></div>${sub.length?`<div class="mb-subtasks">${sub.map(s=>`<button data-action="task-sub-toggle" data-id="${e(t.id)}" data-subid="${e(s.id)}" class="mb-subtask"><span class="mb-subcheck ${s.done?'done':''}">${s.done?'✓':''}</span>${e(s.title)}</button>`).join('')}</div>`:''}${!completed&&!muted?`<div class="mb-task-actions"><button class="mb-soft-btn" data-action="task-review" data-id="${e(t.id)}">Перенести / разобрать</button></div>`:''}</article>`}
function renderTasks(){
 const scope=state.taskScope||'week',list=scopedTasks(scope),all=state.data.tasks||[],done=all.filter(taskIsDone).length,pending=all.filter(t=>!taskIsDone(t)&&!['cancelled','skipped'].includes(t.status)).length,reasons=all.filter(t=>num(t.deferred_count)>0).length;
 const dateGroups=()=>{
  const now=today(),until=plusDays(now,6),active=all.filter(t=>t.task_date&&!['cancelled','skipped'].includes(t.status));
  const ordered=active.filter(t=>t.task_date<=until&&(!taskIsDone(t)||t.task_date>=now)).sort((a,b)=>String(a.task_date).localeCompare(String(b.task_date))||Number(Boolean(b.is_main))-Number(Boolean(a.is_main)));
  const overdue=ordered.filter(t=>t.task_date<now&&!taskIsDone(t));
  const days=Array.from({length:7},(_,i)=>plusDays(now,i));
  const dayBlock=(date,i)=>{const items=ordered.filter(t=>t.task_date===date);const label=i===0?'Сегодня':i===1?'Завтра':i===2?'Послезавтра':ruDate(date);return `<section class="mb8-day-group"><div class="mb8-day-header"><div><h3>${label}</h3><small>${e(ruDate(date))} · ${items.length} задач</small></div><button data-action="new-task" data-date="${date}" aria-label="Добавить задачу на ${e(ruDate(date))}">${icon('plus')}</button></div>${items.length?items.map(taskCard).join(''):`<p class="small muted mb8-empty-day">Пока свободно</p>`}</section>`};
  return `${overdue.length?`<section class="mb8-day-group mb8-overdue"><h3>Просрочено · ${overdue.length}</h3>${overdue.map(taskCard).join('')}</section>`:''}${days.map(dayBlock).join('')}`;
 };
 return `<div class="mb7-simple-page mb7-plan"><div class="mb7-page-title"><span class="mb7-eyebrow">ПЛАН ВОСХОЖДЕНИЯ</span><h1>Мой план</h1><p>Сегодня, завтра и следующие дни — на одном экране. Выбирай дату при создании задачи.</p></div>
 <div class="mb7-plan-actions"><button class="button" data-action="new-task" data-date="${today()}">${icon('plus')} Добавить задачу</button></div>
 <div class="mb7-plan-summary"><div><strong>${pending}</strong><span>В плане</span></div><div><strong>${done}</strong><span>Сделано</span></div><div><strong>${reasons}</strong><span>Переносов</span></div></div>
 <div class="mb7-filters mb7-plan-filters" role="tablist" aria-label="Период задач">${[['week','7 дней'],['today','Сегодня'],['month','Месяц'],['inbox','Без даты'],['all','Все']].map(([id,label])=>`<button role="tab" aria-selected="${scope===id}" class="${scope===id?'selected':''}" data-action="task-scope" data-value="${id}">${label}</button>`).join('')}</div>
 ${scope==='week'?`<div class="mb8-week-groups">${dateGroups()}</div>`:`<section class="mb7-panel mb7-plan-list"><div class="mb7-day-head"><h2>${({today:'Сегодня',month:'В этом месяце',inbox:'Без даты',all:'Все задачи'})[scope]}</h2><span>${list.length} задач</span></div><div class="mb7-task-items">${list.length?list.map(taskCard).join(''):emptyMessage('Пока задач нет','Нажми «Добавить задачу» и выбери день.',`<button class="button" data-action="new-task">Добавить задачу</button>`)}</div></section>`}
 <div class="mb7-foot-note">Любую задачу можно отметить, перенести с причиной или изменить дату через календарь в карточке редактирования.</div></div>`;
}

function renderTodayLinks(){const todayLog=(state.data.daily_logs||[]).find(x=>x.log_date===today());const d=state.data.tasks.filter(x=>x.task_date===today());const done=d.filter(taskIsDone).length;return `<div class="mb-today-banner"><div><div class="eyebrow">ТВОЙ СЛЕДУЮЩИЙ ШАГ</div><strong>${d.length?`${done} из ${d.length} задач сегодня`:'Сегодня можно начать с одного шага'}</strong><p>${todayLog?.reflection_done?'Вечерний итог заполнен.':'Вечером зафиксируй, что получилось и что было трудно.'}</p></div><div class="mb-banner-actions"><button data-page="tasks" class="button secondary">Мои задачи</button><button data-page="reflection" class="button">${todayLog?.reflection_done?'Открыть итог':'Подвести итог'}</button></div></div>`}
function reflectionFromForm(data,old={},finished=false){const mode=String(data.reflection_mode||state.reflectionMode||'quick');const value=k=>String(data[k]??'').trim();const output={...old,log_date:data.log_date||today(),evening_energy:clamp(num(data.energy),1,10),evening_mood:clamp(num(data.mood),1,5),win_of_day:value('win_of_day'),blocked_why:value('blocked_why'),tomorrow_one:value('tomorrow_one'),thoughts:value('thoughts'),reflection_mode:mode,reflection_done:Boolean(finished),reflection_updated_at:new Date().toISOString()};const numeric=['sleep_hours','focus_min','social_min','exercise_min','english_min','learning_min','family_min'];for(const key of numeric)if(data[key]!==undefined)output[key]=String(data[key]).trim()===''?null:Math.max(0,num(data[key]));if(data.learning_kind!==undefined)output.learning_kind=value('learning_kind');if(data.learning_title!==undefined)output.learning_title=value('learning_title');if(data.learning_insight!==undefined)output.learning_insight=value('learning_insight');output.energy=output.evening_energy;output.energy_scale=10;output.mood=output.evening_mood;
 // Don't erase full-review text when quick mode is saved.
 if(mode==='full'){Object.assign(output,{focus_score:clamp(num(data.focus_score),1,10),future_step:value('future_step'),avoidance:value('avoidance'),instead:value('instead'),today_learned:value('today_learned'),lesson_of_day:value('lesson_of_day')})}
 return output;}
function renderReflectionSummary(log,date,allowEdit=false){
 const entries=[['Энергия',log.evening_energy?log.evening_energy+' / 10':''],['Настроение',log.evening_mood?log.evening_mood+' / 5':''],['Моя победа',log.win_of_day],['Что не получилось и почему',log.blocked_why],['Что сделал для будущего',log.future_step],['Чего избегал',log.avoidance],['Что делал вместо важного',log.instead],['Что узнал',log.today_learned],['Главный вывод',log.lesson_of_day],['Мои мысли и идеи',log.thoughts],['Что улучшить завтра',log.tomorrow_one],['Спорт, минут',log.exercise_min],['Английский, минут',log.english_min],['Учёба, минут',log.learning_min],['Что изучал',log.learning_title],['Что применю',log.learning_insight],['Сон, часов',log.sleep_hours],['Работа в фокусе, минут',log.focus_min],['Время с семьёй, минут',log.family_min],['Соцсети, минут',log.social_min]];
 const visible=entries.filter(([title,val])=>String(val??'').trim()!=='');
 return `<div class="mb7-saved-note" role="status"><b>✓ Вечерний итог сохранён</b><small>${e(ruDate(date))} · запись останется в истории восхождения</small></div><div class="mb7-saved-fields">${visible.length?visible.map(([label,value])=>`<div class="mb7-saved-field"><span>${e(label)}</span><p>${e(value)}</p></div>`).join(''):'<p class="small muted">На этот день записан короткий итог.</p>'}</div>${allowEdit?`<div class="mb7-saved-buttons"><button data-page="feed" class="button secondary">${icon('journal')} Посмотреть историю</button><button data-action="reflection-edit" class="button secondary">${icon('pencil')} Редактировать итог</button></div>`:''}`;
}
function renderReflection(){const date=state.reflectionDate||today(),log=state.data.daily_logs.find(x=>x.log_date===date)||{},mode=state.reflectionMode||'quick';const reviewCount=state.data.daily_logs.filter(x=>x.reflection_done).length;const dates=lastDays(7);return `${pageHead('ТВОЙ ДЕНЬ · ОДНА ЗАПИСЬ','Мой дневник','Запиши состояние, факты и мысли за день в одном месте. Две–пять минут, когда удобно.')}<div class="mb-reflection-top"><div class="mb-night"><span>✦</span><div><b>Оглянись на сегодняшний путь</b><p>Даже трудный день можно использовать, чтобы лучше понять себя.</p></div></div><div class="mb-reflection-count">${reviewCount}<small>итогов сохранено</small></div></div><section class="card"><div class="spread mb14"><h2>${log.reflection_done?'Итог сохранён':'Запись вечера'}</h2><span class="pill ${log.reflection_done?'':'gray'}">${log.reflection_done?'✓ Сохранено':'Черновик'}</span></div>${log.reflection_done&&!state.reflectionEditing?renderReflectionSummary(log,date,true):`<div class="mb-tabs mb-mode-tabs">${[['quick','Быстрый · 2 мин'],['full','Полный · 5 мин']].map(([id,label])=>`<button class="${mode===id?'selected':''}" data-action="reflection-mode" data-value="${id}">${label}</button>`).join('')}</div><form data-form="reflection" data-autosave="encrypted" class="stack"><div class="form-grid">${field('log_date','Дата записи','date',date,`required max="${today()}"`)}${selectField('energy','Энергия сегодня',[...Array(10)].map((_,i)=>[i+1,`${i+1} / 10`]),String(log.evening_energy??(log.reflection_done?normalizedEnergy(log):6)))}${selectField('mood','Настроение',[['1','1 · Тяжело'],['2','2 · Ниже обычного'],['3','3 · Нейтрально'],['4','4 · Хорошо'],['5','5 · Отлично']],String(log.evening_mood??(log.reflection_done?log.mood:3)))}${mode==='full'?selectField('focus_score','Концентрация',[...Array(10)].map((_,i)=>[i+1,`${i+1} / 10`]),String(log.focus_score||6)):''}</div><details class="mb8-daily-metrics"><summary>${icon('chart')} Что я сегодня сделал — спорт, знания, фокус <span>необязательно</span></summary><div class="form-grid">${field('sleep_hours','Сон, часов','number',log.sleep_hours??'','min="0" max="24" step="0.1"')}${field('exercise_min','Спорт и движение, минут','number',log.exercise_min??'','min="0" max="1440"')}${field('english_min','Английский, минут','number',log.english_min??'','min="0" max="1440"')}${field('learning_min','Книга / обучение, минут','number',log.learning_min??'','min="0" max="1440"')}${field('focus_min','Работа в фокусе, минут','number',log.focus_min??'','min="0" max="1440"')}${field('social_min','Соцсети, минут','number',log.social_min??'','min="0" max="1440"')}${field('family_min','Время с семьёй, минут','number',log.family_min??'','min="0" max="1440"')}</div>${selectField('learning_kind','Тип обучения',[['video','Видео / курс'],['book','Книга'],['practice','Практика']],log.learning_kind||'video')}${field('learning_title','Что изучил?','text',log.learning_title||'')}${field('learning_insight','Что применю на практике','textarea',log.learning_insight||'')}</details>${field('win_of_day','Моя маленькая или большая победа','textarea',log.win_of_day||'','placeholder="Что сегодня получилось?"')}${field('blocked_why','Что не получилось и почему?','textarea',log.blocked_why||'','placeholder="Факты без обвинения себя"')}${mode==='full'?`${field('future_step','Что я сделал ради будущего?','textarea',log.future_step||'','placeholder="Конкретное действие, а не намерение"')}${field('avoidance','Чего я избегал?','textarea',log.avoidance||'')}${field('instead','Что делал вместо важного?','textarea',log.instead||'')}${field('today_learned','Что узнал, чему научился?','textarea',log.today_learned||'')}${field('lesson_of_day','Главный вывод','textarea',log.lesson_of_day||'')}`:''}${field('thoughts','Мои мысли и идеи','textarea',log.thoughts||'','placeholder="Свободный дневник. Можно оставить пустым."')}${field('tomorrow_one','Одно улучшение завтра','textarea',log.tomorrow_one||'','placeholder="Реальный шаг на 5–15 минут"')}<div class="form-actions mb-save-actions"><span class="small muted" id="mb-autosave">Черновик сохраняется зашифрованно при вводе.</span><button type="submit" class="button">${icon('check')} Завершить обзор</button></div></form>`}</section><section class="card mt20"><div class="card-header"><h2>Неделя: маленькие ежедневные шаги</h2><span class="pill gray">${dates.filter(d=>state.data.daily_logs.some(x=>x.log_date===d&&x.reflection_done)).length}/7 итогов</span></div><div class="mb-reflection-days">${dates.map(d=>{const log=state.data.daily_logs.find(x=>x.log_date===d),done=Boolean(log?.reflection_done);return `<button class="mb-day ${done?'done':''} ${date===d?'active':''}" data-action="reflection-date" data-value="${d}"><span>${new Intl.DateTimeFormat('ru-RU',{weekday:'short'}).format(new Date(d+'T12:00:00'))}</span><b>${d.slice(8)}</b><small>${done?'✓':'·'}</small></button>`}).join('')}</div><p class="small muted mt14">Пропуск — не провал. Можно вернуться к вчерашней записи, не прерывая собственный путь.</p></section>`}
function renderExperiments(){const list=[...(state.data.experiments||[])].sort((a,b)=>String(b.updated_at||b.created_at).localeCompare(String(a.updated_at||a.created_at)));const active=list.filter(x=>x.status==='testing'),concluded=list.filter(x=>['concluded','discarded'].includes(x.status));return `${pageHead('НЕИЗВЕСТНОСТЬ → ПРОВЕРКА','Лаборатория дохода','Тебе не нужно заранее знать идеальный бизнес. Каждую гипотезу можно превратить в маленькую проверку спроса.',`<button class="button" data-action="new-experiment">${icon('plus')} Новая проверка</button>`)}<div class="mb-summary"><div><b>${active.length}</b><span>В работе</span></div><div><b>${concluded.length}</b><span>Завершено</span></div><div><b>${list.reduce((s,x)=>s+num(x.payments),0)}</b><span>Оплат по проверкам</span></div></div><div class="card highlight mb14"><div class="eyebrow">ПРАВИЛО ФОКУСА</div><h2 class="mt8">Проверяй одну гипотезу за раз</h2><p class="small muted mt8">Новая идея — в «Банк идей». Активный эксперимент — здесь. Решение принимается по ответам и оплатам, а не по вдохновению.</p></div><div class="mb-experiment-list">${list.length?list.map(x=>`<article class="card mb-experiment"><div class="spread"><span class="pill ${x.status==='testing'?'':'gray'}">${e(({testing:'Проверяю',paused:'Пауза',concluded:'Завершено',discarded:'Остановлено'})[x.status]||'Новая')}</span><button class="button ghost small" data-action="edit-experiment" data-id="${e(x.id)}">Изменить</button></div><h2 class="mt14">${e(x.title)}</h2><p class="small muted mt8">${e(x.hypothesis)}</p><div class="mb-exp-stats"><span><b>${num(x.contacts)}</b> контактов</span><span><b>${num(x.replies)}</b> ответов</span><span><b>${num(x.payments)}</b> оплат</span><span><b>${money(x.earned_eur)}</b></span></div>${x.learnings?`<p class="mb-exp-note"><b>Вывод:</b> ${e(x.learnings)}</p>`:''}<div class="small muted mt14">Следующий шаг: ${e(x.next_step||x.test_action||'Ещё не записан')}</div>${x.deadline?`<div class="small muted mt8">Контрольная дата: ${ruDate(x.deadline)}</div>`:''}</article>`).join(''):'<section class="card mb-empty"><span>⛰</span><b>Первая проверка ещё впереди</b><p>Начни с идеи, которую реально проверить за семь дней, без больших вложений.</p><button class="button" data-action="new-experiment">Записать первую гипотезу</button></section>'}</div>`}
const SUMMIT_CATEGORIES=[['summit_home','Свой дом','Где и как я хочу жить?'],['summit_car','Машина мечты','Что я хочу себе позволить?'],['summit_finance','Финансовая свобода','Доход, капитал, резервы, отсутствие тяжёлых долгов'],['summit_health','Тело и устойчивость','Форма, спорт, энергия и спокойствие'],['summit_relationships','Семья и окружение','Отношения, друзья, общение'],['summit_experience','Стиль жизни','Путешествия, свобода, новые впечатления'],['summit_values','Кем я хочу стать?','Какие качества хочу развить?']];
function renderSummit(){const p=state.profile||{},debt=currentDebt(),hasVision=SUMMIT_CATEGORIES.some(([key])=>String(p[key]||'').trim()),recent=lastDays(30),counts=recent.map(d=>state.data.tasks.filter(t=>taskIsDone(t)&&String(t.completed_at||t.task_date).slice(0,10)===d).length);return `${pageHead('FROM ZERO TO SUMMIT','Моя вершина','Здесь твой образ будущего. Проценты показываем только по измеримым целям, не по мечтам.')}
<section class="mb-summit-hero"><div><div class="eyebrow">НАЧАЛО ПУТИ</div><h2>Важен каждый<br>настоящий шаг.</h2><p>Желаемая жизнь — ориентир, а реальные действия — маршрут.</p></div></section>
<div class="grid cols2 mt20"><div class="card"><h2>Базовый лагерь</h2><div class="mb-summit-stat"><span>Старт</span><strong>${ruDate(p.started_at||today())}</strong></div><div class="mb-summit-stat"><span>Долг сейчас</span><strong>${money(debt)}</strong></div><div class="mb-summit-stat"><span>Главный фокус</span><strong>${e(p.focus_title||'Найти работающий путь')}</strong></div></div><div class="card"><h2>Прогресс по фактам</h2><p class="small muted">Завершённые задачи за 30 дней</p>${svgChart(counts,recent.map(d=>d.slice(5)))}</div></div>
<section class="card mt20"><div class="spread"><h2>Мои жизненные ориентиры</h2><button class="button small secondary" data-action="summit-edit">${icon('pencil')} ${hasVision?'Редактировать':'Заполнить'}</button></div>${hasVision&&!state.summitEditing?`<div class="mb8-vision-grid">${SUMMIT_CATEGORIES.filter(([key])=>String(p[key]||'').trim()).map(([key,label])=>`<div class="mb7-saved-field"><span>${e(label)}</span><p>${e(p[key])}</p></div>`).join('')}</div>`:`<form data-form="summit" class="stack mt20"><p class="small muted">Не нужно заполнять всё сразу. Можно вернуться позднее.</p><div class="grid cols2">${SUMMIT_CATEGORIES.map(([key,label,hint])=>field(key,label,'textarea',p[key]||'',`placeholder="${e(hint)}"`)).join('')}</div><button class="button" type="submit">${icon('check')} Сохранить мою вершину</button></form>`}</section>
<section class="card mt20"><div class="spread"><div><span class="eyebrow">ИЗМЕРИМЫЙ ПРОГРЕСС</span><h2 class="mt8">Карта целей</h2></div><button data-page="goals" class="button small secondary">Все цели ${icon('arrow')}</button></div><p class="small muted mt8">Только подтверждённые цифры. Для обучения, спорта и дохода показатели обновляются по дневнику и финансам.</p><div class="mb8-goals-stack mt14">${state.data.goals.length?goalCards(state.data.goals.slice(0,4)):emptyMessage('Добавь первую цель','Выбери метрику и следующий конкретный шаг.',`<button data-action="new-goal" class="button">Новая цель</button>`)}</div></section>`}

function achievementItems(){const logs=(state.data.daily_logs||[]),refl=logs.filter(l=>l.reflection_done).sort((a,b)=>a.log_date.localeCompare(b.log_date)),completed=state.data.tasks.filter(taskIsDone),exps=state.data.experiments||[],english=sumOf(logs,'english_min'),learn=sumOf(logs,'learning_min'),sport=new Set([...logs.filter(x=>num(x.exercise_min)>0).map(x=>x.log_date),...state.data.tasks.filter(t=>t.category==='sport'&&taskIsDone(t)).map(t=>t.task_date)]).size,paid=exps.reduce((s,x)=>s+num(x.payments),0)+sumOf(logs,'sales_paid'),debt=currentDebt();let streak=0;for(let i=0;i<365;i++){const date=plusDays(today(),-i);if(i===0&&!refl.some(x=>x.log_date===date))continue;if(refl.some(x=>x.log_date===date))streak++;else break}return [
 ['base','Базовый лагерь','Ты начал личную экспедицию',Boolean(state.profile),'mountain'],['reflect1','Первое наблюдение','Первый завершённый вечерний обзор',refl.length>=1,'journal'],['reflect7','Семь отражений','7 завершённых вечерних итогов',refl.length>=7,'sun'],['streak7','Ритм восхождения','7 дней подряд с обзором',streak>=7,'calendar'],['steps10','Действие важнее планов','10 завершённых задач',completed.length>=10,'check'],['experiment','Первый эксперимент','Проверена хотя бы одна гипотеза',exps.some(x=>x.status==='concluded'),'compass'],['firstpay','Первая подтверждённая оплата','Есть записанная оплата по проверкам или продажам',paid>0,'wallet'],['english','Голос выше','10 часов английского',english>=600,'book'],['learn','Знания в действие','10 часов обучения',learn>=600,'book'],['sport','Сильное тело','10 дней с физической активностью',sport>=10,'heart'],['debt','Минус €500 долга','Остаток долга уменьшился минимум на €500',num(state.profile?.debt_baseline)-debt>=500&&num(state.profile?.debt_baseline)>0,'target']];}
function renderAchievements(){const list=achievementItems(),unlocked=list.filter(x=>x[3]).length;return `${pageHead('GARMIN ДЛЯ ЛИЧНОГО РОСТА','Достижения','Здесь награждаются реальные шаги: выдержка, возвращение к делу, завершение, обучение и первые деньги.')}<div class="mb-summary"><div><b>${unlocked}</b><span>Открыто</span></div><div><b>${list.length}</b><span>Всего достижений</span></div><div><b>${state.data.daily_logs.filter(x=>x.reflection_done).length}</b><span>Вечерних обзоров</span></div></div><section class="mb-badges">${list.map(x=>`<article class="mb-badge ${x[3]?'unlocked':'locked'}"><div class="mb-badge-icon">${icon(x[4])}</div><strong>${e(x[1])}</strong><p>${e(x[2])}</p><span>${x[3]?'✓ Достигнуто':'Ещё впереди'}</span></article>`).join('')}</section><div class="mb-footnote">Нет штрафов за пропуск. Награды не заменяют финансовые результаты и реальные изменения в жизни.</div>`}
function renderMountainWelcome(){const reflected=state.data.daily_logs.some(x=>x.log_date===today()&&x.reflection_done);return `<section class="mb-home-hero"><div class="mb-home-copy"><span>🏔 MONTBLANC · ЛИЧНАЯ ЭКСПЕДИЦИЯ</span><h2>Каждый шаг<br>имеет значение.</h2><p>Ты не обязан знать весь путь. Достаточно честно наблюдать, проверять идеи и двигаться дальше.</p><div class="mb-banner-actions"><button class="button" data-page="tasks">План дня ${icon('arrow')}</button><button class="button secondary" data-page="${reflected?'summit':'reflection'}">${reflected?'Моя вершина':'Итог дня'}</button></div></div></section>`}
function analyticsDates(period){if(period==='year')return [plusDays(today(),-364),today()];if(period==='month')return [plusDays(today(),-29),today()];return [plusDays(today(),-6),today()]}
function insightReport(period=state.analysisPeriod||'week'){const [start,end]=analyticsDates(period),logs=logBetween(start,end),tasks=state.data.tasks.filter(t=>(t.completed_at||t.task_date||'').slice(0,10)>=start&&(t.completed_at||t.task_date||'').slice(0,10)<=end),exps=(state.data.experiments||[]).filter(x=>(x.updated_at||x.started_at||'').slice(0,10)>=start),refl=logs.filter(x=>x.reflection_done),freq={};for(const t of tasks)if(t.reason){freq[t.reason]=(freq[t.reason]||0)+1}return {period,from:start,to:end,entries:logs.length,evening_reviews:refl.length,energy_avg:refl.some(l=>l.evening_energy!=null||l.energy!=null)?Math.round(avg(refl.filter(l=>l.evening_energy!=null||l.energy!=null).map(l=>l.evening_energy??normalizedEnergy(l)))*10)/10:null,mood_avg:refl.some(l=>l.evening_mood!=null||l.mood!=null)?Math.round(avg(refl.filter(l=>l.evening_mood!=null||l.mood!=null).map(l=>l.evening_mood??l.mood))*10)/10:null,focus_minutes:sumOf(logs,'focus_min'),english_minutes:sumOf(logs,'english_min'),learning_minutes:sumOf(logs,'learning_min'),sport_days:logs.filter(x=>num(x.exercise_min)>0).length,tasks:{in_scope:tasks.length,completed:tasks.filter(taskIsDone).length,deferred:tasks.filter(t=>num(t.deferred_count)>0).length,reasons:Object.entries(freq).map(([k,v])=>({reason:reasonLabel[k]||k,count:v}))},experiments:exps.map(x=>({title:x.title,status:x.status,contacts:x.contacts,replies:x.replies,payments:x.payments,earned_eur:x.earned_eur,lessons:x.learnings})),evening_notes:refl.map(l=>({date:l.log_date,win:l.win_of_day,barrier:l.blocked_why,what_avoided:l.avoidance,what_instead:l.instead,what_learned:l.today_learned,thoughts:l.thoughts,tomorrow:l.tomorrow_one})),sales:salesSummary(period==='week'?7:period==='month'?30:365),income_eur:state.data.finance_entries.filter(x=>x.kind==='income'&&x.entry_date>=start&&x.entry_date<=end).reduce((s,x)=>s+num(x.amount_eur),0),debt_current_eur:currentDebt()}}
function insightText(){const p=state.analysisPeriod||'week';return `MONTBLANC — личная экспедиция. Проанализируй ${p==='week'?'неделю':p==='month'?'30 дней':'365 дней'} по фактам. Покажи 3 реальные сильные стороны, повторяющиеся паттерны поведения, причины откладывания только как гипотезы, 3 приоритета на следующую неделю и конкретные действия на 5–15 минут. Отдельно отмечай, где данных недостаточно, не ставь психологических диагнозов и не смешивай мотивацию с доходом. Сначала задай 1 важный уточняющий вопрос, только если это существенно меняет выводы.\n\nДАННЫЕ (проверь личные мысли перед отправкой):\n${JSON.stringify(insightReport(p),null,2)}`}
async function copyInsightReport(){const txt=insightText();try{await navigator.clipboard.writeText(txt);notify('Отчёт скопирован. Проверь текст перед отправкой в ChatGPT.')}catch{const el=document.createElement('textarea');el.value=txt;el.setAttribute('readonly','');el.style.cssText='position:fixed;left:0;top:0;opacity:0';document.body.append(el);el.focus();el.select();const ok=document.execCommand('copy');el.remove();if(ok)notify('Отчёт скопирован. Проверь текст перед отправкой.');else{downloadInsightReport();notify('Копирование недоступно — скачан TXT для отправки.')}}}
function downloadInsightReport(){const url=URL.createObjectURL(new Blob([insightText()],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`montblanc-analysis-${state.analysisPeriod||'week'}-${today()}.txt`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
