 const days=[];for(let d=start,i=0;d<=end&&i<366;d=plusDays(d,1),i++)days.push(d);
 const logs=state.data.daily_logs.filter(l=>l.log_date>=start&&l.log_date<=end),tasks=state.data.tasks.filter(t=>t.task_date>=start&&t.task_date<=end&&!['cancelled','skipped'].includes(t.status));
 const completed=tasks.filter(taskIsDone).length,recorded=logs.filter(l=>l.reflection_done).length,learning=logs.reduce((n,l)=>n+num(l.learning_min),0),english=logs.reduce((n,l)=>n+num(l.english_min),0),sports=v9Period(period).sport,focus=logs.reduce((n,l)=>n+num(l.focus_min),0),income=state.data.finance_entries.filter(f=>f.kind==='income'&&f.entry_date>=start&&f.entry_date<=end).reduce((n,f)=>n+num(f.amount_eur),0),unlocked=achievementItems().filter(x=>x[3]).length;
