function evoProgram(){
 const x=state.profile?.evolution_pro_max;
 if(!x||x.version!==1||typeof x.start!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(x.start))return null;
 return {version:1,start:x.start,mode:x.mode==='gentle'?'gentle':'regular',days:x.days&&typeof x.days==='object'&&!Array.isArray(x.days)?x.days:{}};
}
function evoElapsed(p=evoProgram()){return p?Math.max(0,Math.min(84,deltaDays(p.start,today())+1)):0}
function evoDate(i,p=evoProgram()){return p?plusDays(p.start,Math.max(0,Math.min(83,i))):today()}
function evoIndex(p=evoProgram()){return Math.max(0,Math.min(83,state.evolutionDayIndex==null?evoElapsed(p)-1:state.evolutionDayIndex))}
function evoActivities(index,p=evoProgram()){
 const week=Math.floor(index/7),day=index%7,base=EVO_WEEKS[week][2],suffix=EVO_DAY_STYLES[day][1],gentle=p?.mode==='gentle'||day===6;
 const times=[4,5,Math.min(30,10+week*2),6,Math.min(30,12+week*2)];
 return EVO_SKILLS.map((s,i)=>({id:s[0],name:s[1],icon:s[2],description:base[i]+'. '+suffix,minutes:gentle?Math.max(2,Math.ceil(times[i]/2)):times[i],core:(i+day)%5<3}));
}
function evoStats(p=evoProgram()){
 if(!p)return null;let total=0,active=0,coreDays=0,fullDays=0;
 const elapsed=evoElapsed(p),counts=Object.fromEntries(EVO_SKILLS.map(x=>[x[0],0])),weeks=EVO_WEEKS.map(()=>({done:0,possible:0,active:0}));
 for(let i=0;i<elapsed;i++){
  const date=evoDate(i,p),done=p.days[date]?.done||{},list=evoActivities(i,p),n=list.filter(a=>done[a.id]===true).length;
  total+=n;if(n)active++;if(n===5)fullDays++;if(list.filter(x=>x.core).every(x=>done[x.id]))coreDays++;
  list.filter(x=>done[x.id]).forEach(x=>counts[x.id]++);
  const w=weeks[Math.floor(i/7)];w.done+=n;w.possible+=5;if(n)w.active++;
 }
 return {elapsed,total,possible:elapsed*5,active,coreDays,fullDays,counts,weeks,pct:elapsed?Math.round(100*total/(elapsed*5)):0};
}
function evoAwards(s=evoStats()){
 if(!s)return [];
 const awards=[['🌱','Первый шаг',s.total>=1],['⚡','10 практик',s.total>=10],['🏕️','5 активных дней',s.active>=5],['⭐','Полный день',s.fullDays>=1],['🎙️','Голос',s.counts.charisma>=10],['🦁','Смелость',s.counts.confidence>=10],['🎯','Фокус',s.counts.focus>=10],['✅','Дисциплина',s.counts.discipline>=10],['🏃','Движение',s.counts.body>=10],['🏔️','20 активных дней',s.active>=20],['🧭','50 активных дней',s.active>=50],['🏆','84 дня пути',s.elapsed>=84&&s.active>=50]];
 return awards.map(([icon,name,earned])=>({icon,name,earned}));
}
function evoRecs(p=evoProgram(),stats=evoStats(p)){
 if(!p)return [];
 const since=plusDays(today(),-6),entries=Object.entries(p.days).filter(([day])=>day>=since&&day<=today());
 const energies=entries.map(([,x])=>Number(x.energy)).filter(x=>x>0),low=energies.length&&energies.reduce((a,b)=>a+b,0)/energies.length<=4;
 const active=entries.filter(([,x])=>Object.values(x.done||{}).some(Boolean)).length;
 const counts=Object.fromEntries(EVO_SKILLS.map(s=>[s[0],0]));for(const [,x] of entries)for(const s of EVO_SKILLS)if(x.done?.[s[0]])counts[s[0]]++;
 const weakest=EVO_SKILLS.reduce((best,s)=>counts[s[0]]<counts[best[0]]?s:best,EVO_SKILLS[0]);
 const rec=[];
 if(low)rec.push('По последним записям энергии немного. Выбери бережный режим и не пытайся наверстать пропуски.');
 else if(stats.elapsed>3&&active<=2)rec.push('Для возвращения в ритм сделай одно двухминутное упражнение. Это лучше, чем ждать идеального дня.');
 if(stats.elapsed>2)rec.push('За последние семь дней реже всего встречалась практика «'+weakest[1]+'». Попробуй небольшой шаг в этом направлении.');
 if(active>=4)rec.push('Уже '+active+' активных дней за неделю. Повтори удобное время практики, вместо увеличения нагрузки.');
 if(!rec.length)rec.push('Начни с трёх основных действий, а два дополнительных оставь по желанию.');
 rec.push('В конце дня запиши один факт: что удалось, что мешало и что стоит изменить завтра.');
 return rec.slice(0,3);
}
function evolutionHomeCard(){
 const p=evoProgram(),s=evoStats(p),day=p?Math.max(1,evoElapsed(p)):0,done=p?EVO_SKILLS.filter(x=>p.days[today()]?.done?.[x[0]]).length:0;
 return `<button data-page="evolution" class="ev-home"><span>⚡</span><div><b>EVOLUTION PRO MAX</b><small>${p?'День '+day+'/84 · сегодня '+done+'/5 · всего '+s.total+' практик':'12 недель: харизма, уверенность, фокус, дисциплина и форма'}</small></div><strong>›</strong></button>`;
}
async function evolutionStart(){
 if(!state.local&&!state.demo)throw Error('Сначала открой личный зашифрованный режим на iPhone');
 if(evoProgram())return;
 await saveProfile({...state.profile,evolution_pro_max:{version:1,start:today(),mode:'regular',days:{}}});
 state.evolutionDayIndex=null;
}
async function evolutionIntensity(value){
 const p=evoProgram();if(!p||!['gentle','regular'].includes(value))return;
 await saveProfile({...state.profile,evolution_pro_max:{...p,mode:value}});
}
async function evolutionToggle(skill,date){
 const p=evoProgram();if(!p||!EVO_SKILLS.some(s=>s[0]===skill)||date>today()||deltaDays(p.start,date)<0||deltaDays(p.start,date)>=84)return;
 const old=p.days[date]||{},done={...(old.done||{})};done[skill]=!done[skill];
 await saveProfile({...state.profile,evolution_pro_max:{...p,days:{...p.days,[date]:{...old,done}}}});
}
async function evolutionSaveNote(force=false){
 const f=document.querySelector('form[data-evo-note]');if(!f||!f.isConnected)return;
 const p=evoProgram(),date=f.dataset.date;
 if(!p||date>today()||deltaDays(p.start,date)<0||deltaDays(p.start,date)>=84)return;
 const old=p.days[date]||{},note=String(f.querySelector('textarea[name="note"]')?.value||'').slice(0,1500),energy=Math.max(0,Math.min(10,Math.round(num(f.querySelector('select[name="energy"]')?.value))));
 if(!force&&String(old.note||'')===note&&num(old.energy)===energy)return;
 await saveProfile({...state.profile,evolution_pro_max:{...p,days:{...p.days,[date]:{...old,note,energy}}}});
}
function renderEvolution(){
 const p=evoProgram();
 if(!p)return `<div class="ev-root"><section class="ev-hero"><span>⚡ MONTBLANC · ЛИЧНОЕ ВОСХОЖДЕНИЕ</span><h1>EVOLUTION<br>PRO MAX</h1><p>12 недель, пять жизненных навыков, 84 дня практики. Простой план действий вместо бесконечного анализа себя.</p><div class="ev-pills"><b>84 дня</b><b>5 навыков</b><b>12 этапов</b></div></section><section class="ev-section"><h2>Что будем развивать</h2><div class="ev-skill-grid">${EVO_SKILLS.map(x=>`<div><span>${x[2]}</span><strong>${x[1]}</strong></div>`).join('')}</div><p>Каждый день три основных упражнения и два дополнительных. Прогресс фиксируется без штрафов за пропуски.</p><div class="ev-note">🔒 Все записи войдут в существующий зашифрованный архив MONTBLANC и приватный GitHub Backup.</div>${state.local||state.demo?`<button data-action="evo-start" class="ev-primary">Начать 12-недельную программу →</button>`:`<p>Для сохранения сначала открой личный зашифрованный режим MONTBLANC.</p>`}</section><section class="ev-section"><h2>Этапы развития</h2>${EVO_WEEKS.map((x,i)=>`<div class="ev-week-intro"><b>${i+1}</b><div><strong>${x[0]}</strong><small>${x[1]}</small></div></div>`).join('')}</section></div>`;
 const idx=evoIndex(p),date=evoDate(idx,p),week=Math.floor(idx/7),day=idx%7,theme=EVO_WEEKS[week],style=EVO_DAY_STYLES[day],tasks=evoActivities(idx,p),entry=p.days[date]||{},done=entry.done||{},finished=tasks.filter(x=>done[x.id]).length,future=date>today(),stat=evoStats(p),awards=evoAwards(stat),earned=awards.filter(x=>x.earned).length;
 return `<div class="ev-root"><section class="ev-hero"><span>⚡ EVOLUTION PRO MAX · МАРШРУТ 12 НЕДЕЛЬ</span><h1>Сильнее.<br>Спокойнее.<br>Увереннее.</h1><p>Ежедневные маленькие действия: общение, смелость, фокус, дисциплина и движение.</p><div class="ev-pills"><b>Неделя ${week+1}/12</b><b>День ${idx+1}/84</b></div><div class="ev-track"><i style="width:${Math.round(stat.elapsed/84*100)}%"></i></div><small>Календарный этап: ${Math.round(stat.elapsed/84*100)}% · подтверждено ${stat.total} практик</small></section>
 <section class="ev-section"><div class="ev-heading"><div><span>НЕДЕЛЯ ${week+1}: ${e(theme[0])}</span><h2>${e(style[0])}</h2><p>${e(ruDate(date))} · ${e(theme[1])}</p></div><strong>${finished}/5</strong></div><div class="ev-day-select"><button data-action="evo-day" data-index="${Math.max(0,idx-1)}" ${idx===0?'disabled':''} aria-label="Предыдущий день">‹</button><div>День ${idx+1}<small>${future?'Будущие задания':date===today()?'Сегодня':'Пройденный день'}</small></div><button data-action="evo-day" data-index="${Math.min(83,idx+1)}" ${idx===83?'disabled':''} aria-label="Следующий день">›</button><button class="ev-today" data-action="evo-today">Сегодня</button></div>
 <p>Три основные практики и две дополнительные по желанию. Отмечай только действительно сделанное.</p><div class="ev-exercises">${tasks.map(x=>`<article class="ev-exercise ${done[x.id]?'completed':''}"><button data-action="evo-toggle" data-skill="${x.id}" data-date="${date}" aria-label="${done[x.id]?'Отменить':'Отметить'}: ${x.name}" aria-pressed="${!!done[x.id]}" ${future?'disabled':''}>${done[x.id]?'✓':''}</button><div><strong>${x.icon} ${x.name}</strong><small>${x.core?'Главное':'Дополнительно'} · около ${x.minutes} мин</small><p>${e(x.description)}</p></div></article>`).join('')}</div><div class="ev-intensity"><b>Темп программы</b><div><button data-action="evo-intensity" data-value="gentle" class="${p.mode==='gentle'?'active':''}">Бережный</button><button data-action="evo-intensity" data-value="regular" class="${p.mode==='regular'?'active':''}">Обычный</button></div></div>
 ${!future?`<form class="ev-feedback" data-evo-note data-date="${date}"><label>Энергия <select name="energy"><option value="0">Не отмечено</option>${Array.from({length:10},(_,i)=>i+1).map(x=>`<option value="${x}" ${num(entry.energy)===x?'selected':''}>${x}/10</option>`).join('')}</select></label><label>Что получилось? Что было сложно?<textarea name="note" rows="3" maxlength="1500" placeholder="Короткий вывод дня…">${e(entry.note||'')}</textarea></label><button type="button" data-action="evo-note">Сохранить наблюдение</button></form>`:''}<p class="ev-safety">Если нагрузка не подходит, замени её прогулкой, мягкой разминкой или отдыхом. При боли, головокружении или дискомфорте прекращай тренировку.</p></section>
 <section class="ev-section"><div class="ev-heading"><div><span>📊 АНАЛИТИКА ПО ФАКТАМ</span><h2>Движение за ${stat.elapsed} дней</h2></div><strong>${stat.pct}%</strong></div><div class="ev-metrics"><div><span>Практик выполнено</span><strong>${stat.total}/${stat.possible}</strong></div><div><span>Активных дней</span><strong>${stat.active}</strong></div><div><span>Основных дней</span><strong>${stat.coreDays}</strong></div><div><span>Награды</span><strong>${earned}/${awards.length}</strong></div></div><p>Будущие дни не учитываются. Процент показывает выполнение практик, а не «уровень личности».</p><div class="ev-domains">${EVO_SKILLS.map(x=>`<div><div><span>${x[2]} ${x[1]}</span><b>${stat.counts[x[0]]}</b></div><div class="ev-track"><i style="width:${stat.elapsed?Math.round(stat.counts[x[0]]/stat.elapsed*100):0}%"></i></div></div>`).join('')}</div></section>
 <section class="ev-section"><h2>🧭 Карта 12 недель</h2><p>Выбирай неделю, чтобы просмотреть её программу и прогресс.</p><div class="ev-weeks">${EVO_WEEKS.map((x,i)=>{const s=stat.weeks[i],value=s.possible?Math.round(s.done/s.possible*100):null;return `<button data-action="evo-day" data-index="${i*7}" class="${i===week?'selected':''}"><strong>${i+1}</strong><small>${e(x[0])}</small><div class="ev-track"><i style="width:${value||0}%"></i></div><em>${value===null?'Впереди':value+'%'}</em></button>`}).join('')}</div></section>
 <section class="ev-section"><h2>💡 Рекомендации</h2><div class="ev-recs">${evoRecs(p,stat).map(x=>`<p>${e(x)}</p>`).join('')}</div><p>Советы формируются локально по твоим отметкам и не являются психологической диагностикой или облачным ИИ-анализом.</p></section>
 <section class="ev-section"><h2>🏆 Личные достижения</h2><div class="ev-awards">${awards.map(x=>`<div class="${x.earned?'earned':''}"><span>${x.icon}</span><b>${e(x.name)}</b><small>${x.earned?'✓ Открыто':'Впереди'}</small></div>`).join('')}</div></section><div class="ev-links"><button data-page="reflection">✍ Вечерний дневник →</button><button data-page="route">🏔️ Мой маршрут А → Б →</button></div></div>`;
}
