// Restore is two-phase: verify the archive and its password BEFORE replacing local data.
// An invalid password, malformed archive or cancelled confirmation must leave the old vault intact.
async function verifyEncryptedArchive(parsed,pass){
 if(parsed?.format!=='life-os-v3-encrypted'||parsed.version!==3||parsed.iterations!==310000||typeof parsed.iv!=='string'||typeof parsed.salt!=='string'||typeof parsed.ciphertext!=='string')throw Error('Неизвестный формат архива');
 const salt=fromB64(parsed.salt),iv=fromB64(parsed.iv),ct=fromB64(parsed.ciphertext);
 if(salt.length!==16||iv.length!==12||ct.length<20)throw Error('Архив повреждён');
 const key=await deriveVaultKey(pass,salt);
 const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv},key,ct);
 const obj=JSON.parse(new TextDecoder().decode(plain));
 if(!obj||typeof obj!=='object'||!obj.data||typeof obj.data!=='object'||LEGACY_TABLES.some(t=>!Array.isArray(obj.data[t]))|| (obj.data.experiments!==undefined&&!Array.isArray(obj.data.experiments)))throw Error('Неверное содержимое архива');
 return obj;
}
async function importEncryptedBackup(file){
 if(file.size>12*1024*1024)throw Error('Архив слишком большой (макс. 12 МБ)');
 const parsed=JSON.parse(await file.text());
 if(parsed?.format!=='life-os-v3-encrypted'||parsed.version!==3||!parsed.iv||!parsed.salt||!parsed.ciphertext)throw Error('Это не зашифрованная копия MONTBLANC');
 const overlay=document.createElement('div');overlay.className='overlay';overlay.setAttribute('data-backup-dialog','');
 overlay.innerHTML='<div class="modal" role="dialog" aria-modal="true" aria-label="Восстановление архива"><h2>Восстановить дневник</h2><p class="small muted mt14">Сначала проверим пароль и целостность копии. Текущие записи не затронем, если пароль неверный.</p><form id="backup-import-form" class="stack mt20"><div class="form-field"><label for="backup-pass">Пароль от архива</label><input class="control" type="password" id="backup-pass" autocomplete="off" minlength="12" required/></div><p class="small" id="backup-import-error" role="alert" style="color:#bf4652"></p><div class="form-actions"><button type="button" class="button secondary" id="backup-cancel">Отмена</button><button type="submit" class="button" id="backup-verify">Проверить и восстановить</button></div></form></div>';
 document.body.append(overlay);overlay.querySelector('#backup-pass').focus();
 const cancel=()=>overlay.remove();overlay.querySelector('#backup-cancel').addEventListener('click',cancel);
 overlay.querySelector('#backup-import-form').addEventListener('submit',async ev=>{
  ev.preventDefault();const button=overlay.querySelector('#backup-verify');button.disabled=true;
  const pass=overlay.querySelector('#backup-pass').value;
  try{
   await verifyEncryptedArchive(parsed,pass);
   if(vaultStorage?.getItem(VAULT_KEY)&&!confirm('Заменить текущие записи проверенной резервной копией? Старые данные будут потеряны.')){button.disabled=false;return}
   requireVaultStorage().setItem(VAULT_KEY,JSON.stringify(parsed));
   if(state.local){localCryptoKey=null;state.data=Object.fromEntries(TABLES.map(k=>[k,[]]));state.profile=null;state.local=false}
   overlay.remove();state.mode='local-auth';render();notify('Архив проверен и восстановлен. Введи пароль для входа.');
  }catch(err){overlay.querySelector('#backup-import-error').textContent='Неверный пароль или повреждённый архив. Данные не изменены.';button.disabled=false}
 });
}
document.addEventListener('change',async event=>{if(event.target?.id!=='vault-restore-file')return;const file=event.target.files?.[0];if(!file)return;event.target.value='';try{await importEncryptedBackup(file)}catch(err){displayError(err)}});
