async function boot(){if(!configReady){if(vaultStorage?.getItem(VAULT_KEY)){state.mode='loading';render();if(await tryTrustedUnlock())return}state.mode='landing';render();return}try{state.mode='loading';render();const mod=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.119.0/+esm');client=mod.createClient(cfg.supabaseUrl,cfg.supabasePublishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});const {data,error}=await client.auth.getUser();if(error&&!/session missing/i.test(error.message))console.warn('Auth initial:',error.message);if(data?.user){sessionUser=data.user;await loadRemote()}else{state.mode='auth';render()}}catch(err){state.mode='auth';root.innerHTML='<section class="auth-page"><div class="auth-panel"><h1>Не удалось запустить MONTBLANC</h1><p>Проверьте публичные настройки Supabase и подключение к интернету.</p><div class="notice" id="boot-error"></div><button class="button" onclick="location.reload()">Повторить</button></div></section>';document.getElementById('boot-error').textContent=String(err?.message||err)}}
