const legacyM60Pages={home:M60.home,program:M60.program,diary:M60.diary,progress:M60.progress};
const C60=window.MONTBLANCCHALLENGE.create({state:()=>state,e,num,today,plusDays,deltaDays,ruDate,money,taskIsDone,saveProfile,saveRecord,monthIncome,currentDebt,legacy:M60});
const upgradeBanner=()=>'<section class="m60-card c60-upgrade" aria-label="Новая программа MONTBLANC 14"><div class="c60-upgrade-top"><span>НОВАЯ ПРОГРАММА · MONTBLANC 14.0.1</span><strong>NEW</strong></div><h2>60 дней полной прокачки</h2><p>Полный урок английского, реальная тренировка, заработок, харизма, развитие и дневник. Следующий день открывается после шести подтверждённых результатов.</p>'+(state.local||state.demo?'<button class="m60-primary" data-action="c60-start">Перейти на новый 60-дневный вызов →</button>':'<p>Войди в личный режим, чтобы начать новый вызов.</p>')+'<small>Твой старый маршрут и зашифрованный дневник останутся сохранены. Новый вызов начнётся с первого дня.</small></section>';
M60.home=()=>C60.has()?C60.home():'<div class="m60-page c60-root">'+upgradeBanner()+'</div>'+legacyM60Pages.home();
M60.program=()=>C60.has()?C60.program():'<div class="m60-page c60-root">'+C60.onboard()+'</div><details class="c60-legacy-panel"><summary>Моя прежняя программа и отметки · открыть архив</summary>'+legacyM60Pages.program()+'</details>';
M60.diary=()=>C60.has()?C60.diary():legacyM60Pages.diary();
M60.progress=()=>C60.has()?C60.progress():legacyM60Pages.progress();
let m60DraftTimer=null;
document.addEventListener('input',event=>{
 const f=event.target?.closest?.('form[data-form="mission-journal"]');
 if(!f||!state.local)return;
 f.dataset.dirty='yes';clearTimeout(m60DraftTimer);
 m60DraftTimer=setTimeout(async()=>{
  try{await M60.saveDraft()}catch(err){const s=document.querySelector('.m60-hint');if(s)s.textContent='Не удалось сохранить черновик. Используй кнопку сохранения.'}
 },850);
});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&state.page==='reflection')M60.saveDraft().catch(err=>console.warn('Ошибка сохранения при сворачивании',err))});
document.addEventListener('change',event=>{
 const f=event.target?.closest?.('form[data-form="mission-journal"]');
 if(!f||!state.local)return;
 f.dataset.dirty='yes';clearTimeout(m60DraftTimer);
 m60DraftTimer=setTimeout(()=>M60.saveDraft().catch(()=>{}),350);
});
boot();
